def cash_conversion_label(ocf: Any, net_profit: Any) -> str:
    try:
        ocf_f = float(ocf)
        profit_f = float(net_profit)
    except Exception:
        return "现金流待验证"
    if profit_f <= 0:
        return "利润基数偏弱"
    ratio = ocf_f / profit_f
    if ratio >= 1.0:
        return "现金转化强"
    if ratio >= 0.3:
        return "现金转化一般"
    if ratio >= 0.0:
        return "现金转化偏弱"
    return "经营现金流为负"


def balance_sheet_label(debt_ratio: Any, quick_ratio: Any) -> str:
    try:
        debt = float(debt_ratio)
        quick = float(quick_ratio)
    except Exception:
        return "资产负债待验证"
    if debt >= 65 and quick < 0.8:
        return "杠杆和流动性压力"
    if debt >= 60:
        return "负债率偏高"
    if quick < 0.7:
        return "速动比率偏低"
    return "资产负债可控"


