def source_filename(source: dict[str, Any]) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", source["url"].replace("https://", "").replace("http://", ""))
    if cleaned.lower().endswith(".pdf"):
        return cleaned[:160] + ".pdf"
    return cleaned[:160] + ".html"


def capture_sources() -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    captured: list[dict[str, Any]] = []
    failed: list[dict[str, Any]] = []
    opener = urllib.request.build_opener()
    opener.addheaders = [("User-Agent", "Mozilla/5.0 AStockResearchBot/1.0")]
    for source in SOURCES:
        rel = Path("sources/public-web-20260628") / source_filename(source)
        dest = CASE / rel
        if dest.exists() and dest.stat().st_size > 0:
            body = dest.read_bytes()
            captured.append(
                {
                    **source,
                    "path": str(rel),
                    "size": dest.stat().st_size,
                    "sha256": hashlib.sha256(body).hexdigest(),
                    "captured_at": datetime.now(timezone(timedelta(hours=8))).isoformat(),
                    "capture_status": "ok",
                    "capture_method": "cache_hit",
                }
            )
            continue
        try:
            capture_method = "urllib"
            try:
                with opener.open(source["url"], timeout=12) as resp:
                    body = resp.read()
            except Exception as urllib_exc:
                response = requests.get(
                    source["url"],
                    timeout=(5, 20),
                    headers={"User-Agent": "Mozilla/5.0 AStockResearchBot/1.0"},
                )
                response.raise_for_status()
                body = response.content
                capture_method = f"requests_fallback_after_urllib_error:{urllib_exc}"
            dest.write_bytes(body)
            record = {
                **source,
                "path": str(rel),
                "size": dest.stat().st_size,
                "sha256": hashlib.sha256(body).hexdigest(),
                "captured_at": datetime.now(timezone(timedelta(hours=8))).isoformat(),
                "capture_status": "ok",
            }
            if capture_method != "urllib":
                record["capture_method"] = capture_method
            captured.append(record)
        except Exception as exc:  # keep report build going
            if dest.exists() and dest.stat().st_size > 0:
                body = dest.read_bytes()
                captured.append(
                    {
                        **source,
                        "path": str(rel),
                        "size": dest.stat().st_size,
                        "sha256": hashlib.sha256(body).hexdigest(),
                        "captured_at": datetime.now(timezone(timedelta(hours=8))).isoformat(),
                        "capture_status": "ok",
                        "capture_method": "cached_after_fetch_error",
                        "fetch_error": str(exc),
                    }
                )
            else:
                failed.append({**source, "error": str(exc), "capture_status": "failed"})
    return captured, failed


def clean_cell(value: Any) -> Any:
    if value is None:
        return None
    try:
        if value != value:
            return None
    except Exception:
        pass
    text = str(value).strip()
    if text in {"", "nan", "NaN", "None"}:
        return None
    return value


def is_broker_research_sample(row: dict[str, Any]) -> bool:
    quality = str(row.get("data_quality") or "")
    if quality in {"public_source_no_report_found", "public_source_request_failed", "not_refreshed_default_snapshot"}:
        return False
    institution = str(row.get("institution") or "").strip()
    report_name = str(row.get("report_name") or "").strip()
    return institution not in {"", "未获取"} and report_name not in {
        "",
        "公开研报快照未在本轮稳定获取；保留为缺口状态",
        "东方财富公开个股研报接口未返回稳定样本；保留为缺口状态",
    }


