def fetch_broker_research_snapshot() -> dict[str, Any]:
    cache_path = CASE / "data/broker_research_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_BROKER_REPORTS") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            cached_real = cached.get("real_covered_tickers")
            if cached_real is None:
                cached_real = len({str(r.get("ticker")) for r in cached.get("rows", []) if is_broker_research_sample(r)})
            if cached_real >= 14 and cached.get("rows"):
                cached.update(broker_research_metadata(cached.get("rows", []), cached.get("errors", [])))
                cached["cache_used"] = True
                return cached
        except Exception:
            pass
    if os.getenv("ASTOCK_REFRESH_BROKER_REPORTS") != "1":
        return fallback_broker_research_snapshot()
    try:
        import requests  # noqa: PLC0415
    except Exception as exc:
        return {
            "schema": "astock.broker_research_snapshot.v1",
            "generated_at": now_cst(),
            "source": "eastmoney.reportapi.report.list",
            "rows": [],
            "errors": [{"stage": "import_requests", "error": str(exc)}],
        }

    rows: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    current_year = datetime.now(timezone(timedelta(hours=8))).year
    for ticker in TICKERS:
        code = ticker["code"]
        params = {
            "industryCode": "*",
            "pageSize": "3",
            "industry": "*",
            "rating": "*",
            "ratingChange": "*",
            "beginTime": "2000-01-01",
            "endTime": f"{current_year + 1}-01-01",
            "pageNo": "1",
            "fields": "",
            "qType": "0",
            "orgCode": "",
            "code": code,
            "rcode": "",
            "p": "1",
            "pageNum": "1",
            "pageNumber": "1",
        }
        try:
            resp = requests.get(
                "https://reportapi.eastmoney.com/report/list",
                params=params,
                headers={"User-Agent": "Mozilla/5.0"},
                timeout=(5, 8),
            )
            resp.raise_for_status()
            payload = resp.json()
        except Exception as exc:
            errors.append({"ticker": code, "company": ticker["name"], "error": str(exc)})
            rows.append(broker_research_gap_row(ticker, str(exc)))
            continue
        data = payload.get("data") or []
        if not data:
            errors.append({"ticker": code, "company": ticker["name"], "error": "empty"})
            rows.append(broker_research_gap_row(ticker, "empty"))
            continue
        api_year = int(payload.get("currentYear") or current_year)
        for i, row in enumerate(data, start=1):
            info_code = clean_cell(row.get("infoCode"))
            date_text = str(clean_cell(row.get("publishDate")) or "未披露").split(" ", 1)[0]
            rows.append(
                {
                    "rank": i,
                    "ticker": str(clean_cell(row.get("stockCode")) or code),
                    "company": str(clean_cell(row.get("stockName")) or ticker["name"]),
                    "report_name": str(clean_cell(row.get("title")) or ""),
                    "rating": str(clean_cell(row.get("emRatingName")) or "未披露"),
                    "institution": str(clean_cell(row.get("orgSName")) or clean_cell(row.get("orgName")) or "未披露"),
                    "report_count_1m": clean_cell(row.get("count")),
                    "eps_2026": clean_cell(row.get("predictThisYearEps")) if api_year == 2026 else None,
                    "pe_2026": clean_cell(row.get("predictThisYearPe")) if api_year == 2026 else None,
                    "eps_2027": clean_cell(row.get("predictNextYearEps")) if api_year == 2026 else None,
                    "pe_2027": clean_cell(row.get("predictNextYearPe")) if api_year == 2026 else None,
                    "eps_2028": clean_cell(row.get("predictNextTwoYearEps")) if api_year == 2026 else None,
                    "pe_2028": clean_cell(row.get("predictNextTwoYearPe")) if api_year == 2026 else None,
                    "industry": str(clean_cell(row.get("indvInduName")) or clean_cell(row.get("industryName")) or "未披露"),
                    "date": date_text,
                    "pdf_url": f"https://pdf.dfcfw.com/pdf/H3_{info_code}_1.pdf" if info_code else "",
                    "theme": ticker["theme"],
                    "data_quality": "public_em_research_report",
                }
            )
    return {
        "schema": "astock.broker_research_snapshot.v1",
        "generated_at": now_cst(),
        "source": "eastmoney.reportapi.report.list",
        "top_n_per_ticker": 3,
        "rows": rows,
        "errors": errors,
        **broker_research_metadata(rows, errors),
    }


def broker_research_latest_by_ticker() -> dict[str, dict[str, Any]]:
    latest: dict[str, dict[str, Any]] = {}
    for row in BROKER_RESEARCH_SNAPSHOT.get("rows", []):
        code = str(row.get("ticker", ""))
        if code and code not in latest:
            latest[code] = row
    return latest


def broker_research_snapshot_md() -> str:
    rows = BROKER_RESEARCH_SNAPSHOT.get("rows", [])
    errors = BROKER_RESEARCH_SNAPSHOT.get("errors", [])
    latest = list(broker_research_latest_by_ticker().values())
    table_rows = [
        [
            r["ticker"],
            r["company"],
            r["institution"],
            r["date"],
            reader_text(r["report_name"]),
            r["rating"],
            fmt_num(r.get("eps_2026"), 2),
            fmt_num(r.get("pe_2026"), 1),
            r["pdf_url"],
        ]
        for r in latest
    ]
    real_covered = BROKER_RESEARCH_SNAPSHOT.get("real_covered_tickers")
    if real_covered is None:
        real_covered = len({str(r.get("ticker")) for r in rows if is_broker_research_sample(r)})
    recent_covered = BROKER_RESEARCH_SNAPSHOT.get("recent_covered_tickers", 0)
    forecast_covered = BROKER_RESEARCH_SNAPSHOT.get("forecast_covered_tickers", 0)
    gap_tickers = BROKER_RESEARCH_SNAPSHOT.get("gap_tickers") or [
        ticker["code"] for ticker in TICKERS if ticker["code"] not in {str(r.get("ticker")) for r in rows if is_broker_research_sample(r)}
    ]
    stale_tickers = BROKER_RESEARCH_SNAPSHOT.get("stale_tickers") or []
    no_forecast_tickers = BROKER_RESEARCH_SNAPSHOT.get("no_forecast_tickers") or []
    err_text = "无" if not errors else "；".join(f"{e.get('ticker', e.get('stage'))}:{e.get('error')}" for e in errors[:8])
    return "# 公开个股研报快照\n\n门禁状态：有条件通过。该快照来自东方财富公开个股研报接口，补充公开机构标题、评级、2026E每股收益/市盈率样本和PDF链接；它不是付费Wind/Choice一致预期，不能替代本报告估值模型。接口为空的缺口行不参与券商锚估值权重；样本陈旧或缺少2026E每股收益/市盈率的标的，只能作为覆盖热度和历史叙事参考。\n\n" + md_table(
        ["代码", "名称", "机构", "日期", "报告名称", "评级", "2026E每股收益", "2026E市盈率", "PDF"],
        table_rows,
    ) + f"\n\n- 原始行数：{len(rows)}\n- 展示标的：{BROKER_RESEARCH_SNAPSHOT.get('covered_tickers', 0)}\n- 真实研报覆盖：{real_covered}\n- 近三年样本覆盖：{recent_covered}\n- 2026E每股收益/市盈率样本覆盖：{forecast_covered}\n- 缺口标的：{','.join(gap_tickers) if gap_tickers else '无'}\n- 样本陈旧标的：{','.join(stale_tickers) if stale_tickers else '无'}\n- 缺少2026E预测标的：{','.join(no_forecast_tickers) if no_forecast_tickers else '无'}\n- 抓取错误：{err_text}\n"


def public_broker_report_year(row: dict[str, Any]) -> int | None:
    date_text = str(row.get("date") or "")
    if len(date_text) < 4:
        return None
    try:
        return int(date_text[:4])
    except Exception:
        return None


def public_broker_numeric_values(samples: list[dict[str, Any]], key: str) -> list[float]:
    values: list[float] = []
    for sample in samples:
        value = safe_float_value(sample.get(key))
        if value is not None:
            values.append(value)
    return values


def public_broker_avg(values: list[float]) -> float | None:
    if not values:
        return None
    return sum(values) / len(values)


def public_broker_range(values: list[float], digits: int = 2) -> str:
    if not values:
        return "未披露"
    if len(values) == 1:
        return fmt_num(values[0], digits)
    return f"{fmt_num(min(values), digits)}-{fmt_num(max(values), digits)}"


def public_broker_institutions(samples: list[dict[str, Any]]) -> list[str]:
    seen: set[str] = set()
    institutions: list[str] = []
    for sample in samples:
        name = str(sample.get("institution") or "未披露")
        if name not in seen:
            seen.add(name)
            institutions.append(name)
    return institutions


def public_broker_forecast_rows(valuation_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    sample_by_ticker: dict[str, list[dict[str, Any]]] = {}
    for sample in BROKER_RESEARCH_SNAPSHOT.get("rows", []):
        if not is_broker_research_sample(sample):
            continue
        code = str(sample.get("ticker") or "")
        if not code:
            continue
        sample_by_ticker.setdefault(code, []).append(sample)

    output: list[dict[str, Any]] = []
    for valuation_row in valuation_rows:
        code = str(valuation_row["code"])
        samples = sample_by_ticker.get(code, [])
        samples = sorted(samples, key=lambda x: str(x.get("date") or ""), reverse=True)
        recent_samples = [s for s in samples if (public_broker_report_year(s) or 0) >= 2024]
        forecast_samples = [s for s in samples if safe_float_value(s.get("eps_2026")) is not None or safe_float_value(s.get("pe_2026")) is not None]
        eps_values = public_broker_numeric_values(forecast_samples, "eps_2026")
        pe_values = public_broker_numeric_values(forecast_samples, "pe_2026")
        eps_avg = public_broker_avg(eps_values)
        pe_avg = public_broker_avg(pe_values)
        eps_min = min(eps_values) if eps_values else None
        eps_max = max(eps_values) if eps_values else None
        pe_min = min(pe_values) if pe_values else None
        pe_max = max(pe_values) if pe_values else None
        eps_spread_pct = (eps_max - eps_min) / eps_avg if eps_avg and eps_min is not None and eps_max is not None else None
        astock_eps = safe_float_value(valuation_row.get("eps_2026e"))
        astock_delta = (astock_eps - eps_avg) / eps_avg if eps_avg not in (None, 0) and astock_eps is not None else None
        institutions = public_broker_institutions(samples)
        latest = samples[0] if samples else {}
        if len(forecast_samples) >= 2 and recent_samples:
            forecast_quality = "多样本可用"
            external_anchor_use = "可作为公开每股收益/市盈率分歧锚，但不替代付费一致预期"
        elif len(forecast_samples) == 1 and recent_samples:
            forecast_quality = "单样本可用"
            external_anchor_use = "只作单点外部参照，不进入一致预期权重"
        elif samples and not recent_samples:
            forecast_quality = "样本陈旧"
            external_anchor_use = "仅作历史覆盖热度，不进入券商锚权重"
        else:
            forecast_quality = "缺少2026E预测"
            external_anchor_use = "不能作为盈利预测锚"
        output.append(
            {
                "ticker": code,
                "company": valuation_row["name"],
                "theme": valuation_row["theme"],
                "sample_count": len(samples),
                "recent_sample_count": len(recent_samples),
                "forecast_sample_count": len(forecast_samples),
                "institutions": institutions,
                "latest_report_date": latest.get("date") or "未披露",
                "latest_report_name": latest.get("report_name") or "未披露",
                "latest_rating": latest.get("rating") or "未披露",
                "latest_pdf_url": latest.get("pdf_url") or "",
                "eps_2026_samples": eps_values,
                "eps_2026_avg": eps_avg,
                "eps_2026_min": eps_min,
                "eps_2026_max": eps_max,
                "eps_2026_range": public_broker_range(eps_values, 2),
                "eps_2026_spread_pct": eps_spread_pct,
                "pe_2026_samples": pe_values,
                "pe_2026_avg": pe_avg,
                "pe_2026_min": pe_min,
                "pe_2026_max": pe_max,
                "pe_2026_range": public_broker_range(pe_values, 1),
                "astock_eps_2026e": astock_eps,
                "astock_vs_public_broker_eps_pct": astock_delta,
                "forecast_quality": forecast_quality,
                "external_anchor_use": external_anchor_use,
                "evidence_boundary": "公开接口摘要，不是Wind/Choice一致预期；不含完整券商假设、目标价历史和模型表。",
                "remaining_gap": "券商全文假设、付费一致预期、目标价历史、收入/利润分部预测和可复核模型表。",
            }
        )
    return output


def public_broker_forecast_packet(valuation_rows: list[dict[str, Any]]) -> dict[str, Any]:
    rows = public_broker_forecast_rows(valuation_rows)
    return {
        "schema": "astock.public_broker_forecast_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "source": BROKER_RESEARCH_SNAPSHOT.get("source", "eastmoney.reportapi.report.list"),
        "rows": rows,
        "coverage": {
            "covered_tickers": len(rows),
            "forecast_tickers": sum(1 for r in rows if r["forecast_sample_count"] > 0),
            "multi_sample_forecast_tickers": sum(1 for r in rows if r["forecast_sample_count"] >= 2),
            "stale_or_no_forecast_tickers": [r["ticker"] for r in rows if r["forecast_quality"] in {"样本陈旧", "缺少2026E预测"}],
        },
        "use_boundary": "公开券商预测分歧只用于外部锚和AStock假设差异审计；不得替代付费一致预期、券商全文假设、订单、ASP、客户份额或单品毛利。",
    }


