def load_public_broker_fulltext_manifest() -> list[dict[str, Any]]:
    manifest_path = CASE / "sources/broker-reports/2026-06-29/manifest.json"
    if not manifest_path.exists():
        return []
    try:
        rows = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception:
        return []
    return rows if isinstance(rows, list) else []


def compact_source_text(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip()


def broker_fulltext_flag(text: str, terms: list[str]) -> bool:
    return any(term in text for term in terms)


def broker_fulltext_target_signal(text: str) -> str:
    patterns = [
        r"目标价[（(]?元[）)]?\s*([0-9]+(?:\.[0-9]+)?)",
        r"目标价[（(]?人民币[）)]?[:：]?\s*([0-9]+(?:\.[0-9]+)?)",
        r"目标价[:：]?\s*([0-9]+(?:\.[0-9]+)?)\s*元",
    ]
    for pattern in patterns:
        match = re.search(pattern, text)
        if match:
            return f"全文检出目标价字段：{match.group(1)}元"
    if "目标价" in text:
        return "全文检出目标价字段但未稳定抽出数值"
    return "全文未检出目标价字段"


def broker_fulltext_assumption_signal(code: str, text: str) -> str:
    ticker = {r["code"]: r for r in TICKERS}.get(code, {})
    theme = ticker.get("theme", "")
    signals: list[str] = []
    if broker_fulltext_flag(text, ["2026E"]) and broker_fulltext_flag(text, ["2027E"]):
        signals.append("含2026E/2027E预测表")
    elif broker_fulltext_flag(text, ["2026E"]):
        signals.append("含2026E预测表")
    if theme == "钨":
        if broker_fulltext_flag(text, ["钨价", "钨原料", "钨精矿", "硬质合金"]):
            signals.append("覆盖钨价/资源/硬质合金假设")
    elif theme == "氟化工":
        if broker_fulltext_flag(text, ["制冷剂", "配额", "氟化工", "高端氟材料", "PFA"]):
            signals.append("覆盖制冷剂/含氟材料景气假设")
    else:
        if broker_fulltext_flag(text, ["六氟化钨", "三氟化氮", "电子特气", "光刻气", "前驱体"]):
            signals.append("覆盖电子特气/半导体材料假设")
    if broker_fulltext_flag(text, ["风险提示"]):
        signals.append("含风险提示")
    return "；".join(signals) if signals else "全文已归档但主题假设需人工复核"


def broker_fulltext_matched_terms(text: str, terms: list[str], limit: int = 5) -> str:
    matched = []
    for term in terms:
        if term in text and term not in matched:
            matched.append(term)
        if len(matched) >= limit:
            break
    return "、".join(matched) if matched else "未检出"


def broker_fulltext_product_terms(theme: str) -> list[str]:
    common = ["半导体材料", "电子材料", "电子特气", "先进制程", "国产替代"]
    if theme == "钨":
        return ["钨价", "钨精矿", "APT", "钨粉", "硬质合金", "刀具", "高纯钨", "钨靶材"] + common
    if theme == "氟化工":
        return ["制冷剂", "R32", "R125", "R134a", "配额", "高端氟材料", "PFA", "氟化液", "电子级氢氟酸", "六氟磷酸锂"] + common
    return ["六氟化钨", "三氟化氮", "WF6", "NF3", "前驱体", "光刻气", "电子级氯气", "电子级氯化氢", "稀有气体"] + common


def broker_fulltext_signal_terms(code: str, text: str) -> dict[str, str]:
    ticker = {r["code"]: r for r in TICKERS}.get(code, {})
    theme = ticker.get("theme", "")
    product_terms = broker_fulltext_matched_terms(text, broker_fulltext_product_terms(theme))
    customer_terms = broker_fulltext_matched_terms(
        text,
        ["中芯国际", "华虹", "长鑫", "长存", "台积电", "晶圆厂", "客户认证", "验证", "批量供应", "ASML", "GIGAPHOTON", "核心客户"],
    )
    order_terms = broker_fulltext_matched_terms(
        text,
        ["订单", "合同", "长协", "定点", "中标", "供货", "交付", "出货", "销量", "产能利用率", "剩余履约义务"],
    )
    price_margin_terms = broker_fulltext_matched_terms(
        text,
        ["均价", "售价", "价格", "涨价", "价差", "平均单价", "毛利率", "毛利", "成本", "盈利能力"],
    )
    risk_terms = broker_fulltext_matched_terms(
        text,
        ["风险提示", "价格波动", "需求不及预期", "产能释放", "客户认证", "技术迭代", "原材料", "汇率", "贸易摩擦", "政策"],
    )
    has_hard_field_terms = any(x != "未检出" for x in [customer_terms, order_terms, price_margin_terms])
    if has_hard_field_terms:
        p0_signal = "检出客户/订单/价格/毛利相关词，作为人工复核入口；未形成可入模硬字段"
    elif product_terms != "未检出":
        p0_signal = "检出产品/主题词；未检出客户、订单、价格或毛利硬字段"
    else:
        p0_signal = "未检出可用于P0复核的主题硬字段"
    return {
        "product_terms": product_terms,
        "customer_certification_terms": customer_terms,
        "order_delivery_terms": order_terms,
        "price_margin_terms": price_margin_terms,
        "risk_terms": risk_terms,
        "p0_evidence_signal": p0_signal,
        "fulltext_review_use": "用于人工复核券商全文假设和P0补证入口，不直接进入增长每股收益或目标价上修",
    }


def broker_fulltext_normalize_forecast_line(text: str) -> str:
    line = text.strip().replace("，", ",")
    line = re.sub(r"(?<=\d)\s*\.\s*(?=\d)", ".", line)
    line = re.sub(r"(?<=\d)\s+(?=\d)", "", line)
    return line


def broker_fulltext_is_year_line(line: str) -> bool:
    return bool(re.fullmatch(r"20\d{2}[AEF]?", broker_fulltext_normalize_forecast_line(line).replace(" ", "")))


def broker_fulltext_year_from_line(line: str) -> int | None:
    match = re.search(r"20\d{2}", line)
    return int(match.group(0)) if match else None


def broker_fulltext_numeric_line_values(line: str) -> list[float]:
    normalized = broker_fulltext_normalize_forecast_line(line)
    stripped = re.sub(r"[-+]?\d[\d,]*(?:\.\d+)?%?", "", normalized)
    stripped = stripped.replace("/", "").replace(" ", "").replace("：", "").replace(":", "")
    if stripped not in {"", "--", "—"}:
        return []
    values: list[float] = []
    for raw in re.findall(r"[-+]?\d[\d,]*(?:\.\d+)?%?", normalized):
        try:
            values.append(float(raw.rstrip("%").replace(",", "")))
        except Exception:
            continue
    return values


def broker_fulltext_metric_type(line: str) -> str | None:
    compact = broker_fulltext_normalize_forecast_line(line).replace(" ", "")
    if any(token in compact for token in ["实现", "预计", "分别", "同比", "季度", "对应", "报告", "数据来源", "资料来源", "当前股价", "收盘价", "总市值", "流通"]):
        return None
    if len(compact) > 34:
        return None
    if ("营业总收入" in compact or "营业收入" in compact or "主营收入" in compact) and "增长率" not in compact:
        return "revenue"
    if "营业收入增长率" in compact or "主营收入增长率" in compact:
        return "revenue_growth"
    if ("归属母公司股东净利润" in compact or "归属母公司净利润" in compact or "归母净利润" in compact or "归母净利" in compact) and "增长率" not in compact:
        return "net_profit"
    if "净利润增长率" in compact or "归母净利润增长率" in compact:
        return "profit_growth"
    if "增长率" in compact or compact == "同比增减":
        return "growth"
    if "每股收益" in compact or "EPS" in compact or "每股盈余" in compact:
        return "eps"
    if "市盈率" in compact or "P/E" in compact or compact == "PE":
        return "pe"
    if compact == "PB" or "市净率" in compact:
        return "pb"
    if "ROE" in compact:
        return "roe"
    if "EBITDA" in compact:
        return "ebitda"
    return None


def broker_fulltext_metric_factor(line: str) -> float:
    normalized = broker_fulltext_normalize_forecast_line(line)
    if "百万元" in normalized:
        return 0.01
    if "亿元" in normalized:
        return 1.0
    return 0.01


def broker_fulltext_years_near(lines: list[str], idx: int) -> list[int]:
    years: list[int] = []
    for line in lines[max(0, idx - 22): min(len(lines), idx + 25)]:
        if broker_fulltext_is_year_line(line):
            year = broker_fulltext_year_from_line(line)
            if year and year not in years:
                years.append(year)
    return years


def broker_fulltext_extract_rowwise_metric(lines: list[str], metric: str) -> tuple[float, str] | None:
    for idx, line in enumerate(lines):
        if broker_fulltext_metric_type(line) != metric:
            continue
        years = broker_fulltext_years_near(lines, idx)
        if 2026 not in years or len(years) < 2:
            continue
        values: list[float] = []
        skipped = 0
        for cursor in range(idx + 1, min(len(lines), idx + 32)):
            metric_at_cursor = broker_fulltext_metric_type(lines[cursor])
            if metric_at_cursor and values:
                break
            if metric_at_cursor and not values:
                break
            if any(token in lines[cursor] for token in ["资料来源", "数据来源", "风险提示", "请务必", "免责声明"]):
                break
            if broker_fulltext_is_year_line(lines[cursor]):
                continue
            line_values = broker_fulltext_numeric_line_values(lines[cursor])
            if line_values:
                values.extend(line_values)
                if len(values) >= len(years):
                    break
            else:
                skipped += 1
                if skipped > 6 and not values:
                    break
        year_idx = years.index(2026)
        if len(values) > year_idx:
            return values[year_idx] * broker_fulltext_metric_factor(line), "rowwise"
    return None


def broker_fulltext_extract_year_block_metric(lines: list[str], metric: str) -> tuple[float, str] | None:
    for start in range(len(lines)):
        metrics: list[str] = []
        metric_lines: list[str] = []
        first_year: int | None = None
        for cursor in range(start, min(len(lines), start + 35)):
            if broker_fulltext_is_year_line(lines[cursor]):
                first_year = cursor
                break
            metric_at_cursor = broker_fulltext_metric_type(lines[cursor])
            if metric_at_cursor:
                metrics.append(metric_at_cursor)
                metric_lines.append(lines[cursor])
        if first_year is None or "revenue" not in metrics or "net_profit" not in metrics or metric not in metrics:
            continue
        events: list[tuple[str, float | int]] = []
        for line in lines[first_year: min(len(lines), first_year + 90)]:
            if any(token in line for token in ["资料来源", "数据来源", "风险提示", "请务必", "免责声明"]):
                break
            if broker_fulltext_metric_type(line):
                continue
            if broker_fulltext_is_year_line(line):
                year = broker_fulltext_year_from_line(line)
                if year:
                    events.append(("year", year))
                continue
            for value in broker_fulltext_numeric_line_values(line):
                events.append(("num", value))
        years_before_first_number: list[int] = []
        first_number_seen = False
        current_year: int | None = None
        year_values: dict[int, list[float]] = {}
        for event_type, value in events:
            if event_type == "year":
                current_year = int(value)
                if not first_number_seen:
                    years_before_first_number.append(current_year)
                year_values.setdefault(current_year, [])
            else:
                first_number_seen = True
                if current_year is not None:
                    year_values.setdefault(current_year, []).append(float(value))
        metric_idx = metrics.index(metric)
        if len(years_before_first_number) > 1:
            years = years_before_first_number
            values = [float(value) for event_type, value in events if event_type == "num"]
            if 2026 in years:
                year_idx = years.index(2026)
                offset = year_idx * len(metrics) + metric_idx
                if len(values) > offset:
                    return values[offset] * broker_fulltext_metric_factor(metric_lines[metric_idx]), "year-block"
        else:
            values = year_values.get(2026, [])
            if len(values) > metric_idx:
                return values[metric_idx] * broker_fulltext_metric_factor(metric_lines[metric_idx]), "year-block"
    return None


def broker_fulltext_extract_narrative_metric(text: str, metric: str) -> tuple[float, str] | None:
    compact = re.sub(r"\s+", " ", broker_fulltext_normalize_forecast_line(text))
    if metric == "revenue":
        patterns = [
            r"2026[-—至~]+2028\s*年[^。；]*?(?:营业收入|主营收入)分别为\s*([-+]?\d+(?:\.\d+)?)",
            r"2025[-—至~]+2027\s*年[^。；]*?(?:营业收入|主营收入)分别为\s*[-+]?\d+(?:\.\d+)?[、/,]\s*([-+]?\d+(?:\.\d+)?)",
        ]
    else:
        patterns = [
            r"2026[-—至~]+2028\s*年[^。；]*?归母净利润分别(?:为|至)?\s*([-+]?\d+(?:\.\d+)?)",
            r"2025[-—至~]+2027\s*年[^。；]*?归母净利润分别为\s*[-+]?\d+(?:\.\d+)?[、/,]\s*([-+]?\d+(?:\.\d+)?)",
            r"2025[-—至~]+2027\s*年[^。；]*?实现归母净利润\s*[-+]?\d+(?:\.\d+)?[、/,]\s*([-+]?\d+(?:\.\d+)?)",
            r"2026、2027、2028\s*年公司分别实现净利润\s*([-+]?\d+(?:\.\d+)?)",
            r"2026[-—至~]+2027\s*年归母净利润预测为\s*([-+]?\d+(?:\.\d+)?)",
            r"26/27/28\s*年归母净利润\s*([-+]?\d+(?:\.\d+)?)/[-+]?\d+(?:\.\d+)?/[-+]?\d+(?:\.\d+)?",
        ]
    for pattern in patterns:
        match = re.search(pattern, compact)
        if match:
            return float(match.group(1)), "narrative"
    return None


def broker_fulltext_forecast_model_fields(text: str) -> dict[str, Any]:
    lines = [broker_fulltext_normalize_forecast_line(line) for line in text.splitlines() if broker_fulltext_normalize_forecast_line(line)]
    revenue = (
        broker_fulltext_extract_rowwise_metric(lines, "revenue")
        or broker_fulltext_extract_year_block_metric(lines, "revenue")
        or broker_fulltext_extract_narrative_metric(text, "revenue")
    )
    net_profit = (
        broker_fulltext_extract_narrative_metric(text, "net_profit")
        or broker_fulltext_extract_rowwise_metric(lines, "net_profit")
        or broker_fulltext_extract_year_block_metric(lines, "net_profit")
    )
    revenue_value = revenue[0] if revenue else None
    net_profit_value = net_profit[0] if net_profit else None
    if revenue_value is not None and net_profit_value is not None:
        parse_status = "2026E营收和归母净利可解析"
        quality = "模型表字段可复核"
    elif revenue_value is not None or net_profit_value is not None:
        parse_status = "2026E营收或归母净利部分可解析"
        quality = "模型表字段部分可复核"
    else:
        parse_status = "未稳定解析2026E营收/归母净利"
        quality = "模型表字段缺失"
    return {
        "broker_revenue_2026e_cny_billion": revenue_value,
        "broker_revenue_2026e_source": revenue[1] if revenue else "未解析",
        "broker_net_profit_2026e_cny_billion": net_profit_value,
        "broker_net_profit_2026e_source": net_profit[1] if net_profit else "未解析",
        "broker_forecast_model_parse_status": parse_status,
        "broker_forecast_model_quality": quality,
        "broker_forecast_model_use": "只用于公开券商全文模型表复核和AStock假设交叉检查，不替代付费一致预期或公司单品订单/ASP/毛利",
    }


def public_broker_fulltext_rows() -> list[dict[str, Any]]:
    by_code = {r["code"]: r for r in TICKERS}
    rows: list[dict[str, Any]] = []
    for item in load_public_broker_fulltext_manifest():
        code = str(item.get("ticker") or "")
        ticker = by_code.get(code, {})
        text_path = CASE / str(item.get("text") or "")
        source_path = CASE / str(item.get("file") or "")
        raw_text = ""
        text = ""
        if text_path.exists():
            raw_text = text_path.read_text(encoding="utf-8", errors="ignore")
            text = compact_source_text(raw_text)
        has_text = bool(text)
        signal_terms = broker_fulltext_signal_terms(code, text) if has_text else {
            "product_terms": "未抽取",
            "customer_certification_terms": "未抽取",
            "order_delivery_terms": "未抽取",
            "price_margin_terms": "未抽取",
            "risk_terms": "未抽取",
            "p0_evidence_signal": "未抽取",
            "fulltext_review_use": "全文未抽取，不能用于复核",
        }
        forecast_model_fields = broker_fulltext_forecast_model_fields(raw_text) if has_text else {
            "broker_revenue_2026e_cny_billion": None,
            "broker_revenue_2026e_source": "未抽取",
            "broker_net_profit_2026e_cny_billion": None,
            "broker_net_profit_2026e_source": "未抽取",
            "broker_forecast_model_parse_status": "未抽取",
            "broker_forecast_model_quality": "模型表字段缺失",
            "broker_forecast_model_use": "全文未抽取，不能用于复核",
        }
        rows.append(
            {
                "ticker": code,
                "company": ticker.get("name") or item.get("name") or code,
                "theme": ticker.get("theme", ""),
                "report_date": item.get("date") or "",
                "report_name": item.get("report_name") or "",
                "rating": item.get("rating") or "未披露",
                "eps_2026": safe_float_value(item.get("eps_2026")),
                "pe_2026": safe_float_value(item.get("pe_2026")),
                "pages": int(item.get("pages") or 0),
                "source_file": str(source_path.relative_to(CASE)) if source_path.exists() else str(item.get("file") or ""),
                "text_file": str(text_path.relative_to(CASE)) if text_path.exists() else str(item.get("text") or ""),
                "text_chars": len(text),
                "fulltext_status": "全文PDF和文本已归档" if source_path.exists() and has_text else "全文归档不完整",
                "target_price_signal": broker_fulltext_target_signal(text) if has_text else "未抽取",
                "assumption_signal": broker_fulltext_assumption_signal(code, text) if has_text else "未抽取",
                "forecast_signal": "全文含2026E/2027E/2028E预测表" if all(x in text for x in ["2026E", "2027E", "2028E"]) else ("全文含部分预测表" if "2026E" in text else "全文未检出预测表"),
                **signal_terms,
                **forecast_model_fields,
                "valuation_use": "用于外部锚质量、券商全文假设存在性和本报告假设差异审计",
                "evidence_boundary": "公开券商全文不得替代公司公告、付费一致预期、订单、合同平均售价、客户份额或单品毛利",
                "remaining_gap": "付费一致预期、完整模型表、分产品订单/价格/毛利仍需后续来源",
            }
        )
    order = {x["code"]: idx for idx, x in enumerate(TICKERS)}
    rows.sort(key=lambda r: order.get(r["ticker"], 999))
    return rows


def public_broker_fulltext_packet() -> dict[str, Any]:
    rows = public_broker_fulltext_rows()
    return {
        "schema": "astock.public_broker_fulltext_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "rows": rows,
        "coverage": {
            "covered_tickers": len({r["ticker"] for r in rows}),
            "archived_pdf_count": sum(1 for r in rows if r["source_file"]),
            "extracted_text_count": sum(1 for r in rows if r["text_chars"] > 0),
            "target_signal_count": sum(1 for r in rows if r["target_price_signal"] not in {"全文未检出目标价字段", "未抽取"}),
            "forecast_table_count": sum(1 for r in rows if "预测表" in r["forecast_signal"] and "未检出" not in r["forecast_signal"]),
            "model_revenue_2026e_tickers": sum(1 for r in rows if r.get("broker_revenue_2026e_cny_billion") is not None),
            "model_net_profit_2026e_tickers": sum(1 for r in rows if r.get("broker_net_profit_2026e_cny_billion") is not None),
            "model_revenue_and_profit_2026e_tickers": sum(1 for r in rows if r.get("broker_revenue_2026e_cny_billion") is not None and r.get("broker_net_profit_2026e_cny_billion") is not None),
            "product_term_tickers": sum(1 for r in rows if r.get("product_terms") not in {"未检出", "未抽取"}),
            "customer_term_tickers": sum(1 for r in rows if r.get("customer_certification_terms") not in {"未检出", "未抽取"}),
            "order_delivery_term_tickers": sum(1 for r in rows if r.get("order_delivery_terms") not in {"未检出", "未抽取"}),
            "price_margin_term_tickers": sum(1 for r in rows if r.get("price_margin_terms") not in {"未检出", "未抽取"}),
        },
        "use_boundary": "公开券商全文只用于外部锚质量审计和假设差异复核，不替代付费一致预期、公司公告、订单、合同平均售价、客户份额或单品毛利。",
        "source_manifest": "sources/broker-reports/2026-06-29/manifest.json",
    }


