def public_broker_coverage_rows(valuation_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    sample_by_ticker: dict[str, list[dict[str, Any]]] = {}
    for sample in BROKER_RESEARCH_SNAPSHOT.get("rows", []):
        if not is_broker_research_sample(sample):
            continue
        code = str(sample.get("ticker") or "")
        if code:
            sample_by_ticker.setdefault(code, []).append(sample)

    rows: list[dict[str, Any]] = []
    for valuation_row in valuation_rows:
        code = str(valuation_row["code"])
        samples = sorted(sample_by_ticker.get(code, []), key=lambda x: str(x.get("date") or ""), reverse=True)
        recent_samples = [s for s in samples if (public_broker_report_year(s) or 0) >= 2024]
        forecast_samples = [
            s
            for s in samples
            if any(safe_float_value(s.get(k)) is not None for k in ["eps_2026", "eps_2027", "eps_2028", "pe_2026", "pe_2027", "pe_2028"])
        ]
        institutions = public_broker_institutions(samples)
        rating_counts: dict[str, int] = {}
        for sample in samples:
            rating = str(sample.get("rating") or "未披露")
            rating_counts[rating] = rating_counts.get(rating, 0) + 1
        rating_mix = "、".join(f"{k}{v}" for k, v in rating_counts.items()) if rating_counts else "无样本"
        forecast_years = [
            year
            for year in ["2026", "2027", "2028"]
            if any(safe_float_value(sample.get(f"eps_{year}")) is not None or safe_float_value(sample.get(f"pe_{year}")) is not None for sample in samples)
        ]
        if len(recent_samples) >= 2 and len(forecast_years) >= 2:
            coverage_quality = "近期多样本多年度"
            anchor_eligibility = "可进入公开外部锚审计，但不能替代付费一致预期"
        elif len(recent_samples) >= 1 and forecast_years:
            coverage_quality = "近期单点或单年度"
            anchor_eligibility = "只能作为单点外部语境，低权重"
        elif samples:
            coverage_quality = "样本陈旧"
            anchor_eligibility = "只证明历史覆盖热度，不进入券商锚"
        else:
            coverage_quality = "无公开样本"
            anchor_eligibility = "不能进入券商锚"
        latest = samples[0] if samples else {}
        rows.append(
            {
                "ticker": code,
                "company": valuation_row["name"],
                "theme": valuation_row["theme"],
                "total_sample_count": len(samples),
                "recent_sample_count": len(recent_samples),
                "forecast_sample_count": len(forecast_samples),
                "institution_count": len(institutions),
                "institutions": institutions,
                "rating_mix": rating_mix,
                "latest_report_date": latest.get("date") or "未披露",
                "latest_institution": latest.get("institution") or "未披露",
                "latest_rating": latest.get("rating") or "未披露",
                "latest_report_name": latest.get("report_name") or "未披露",
                "oldest_report_date": samples[-1].get("date") if samples else "未披露",
                "forecast_years_covered": forecast_years,
                "eps_2026_range": public_broker_range(public_broker_numeric_values(samples, "eps_2026"), 2),
                "eps_2027_range": public_broker_range(public_broker_numeric_values(samples, "eps_2027"), 2),
                "eps_2028_range": public_broker_range(public_broker_numeric_values(samples, "eps_2028"), 2),
                "pe_2026_range": public_broker_range(public_broker_numeric_values(samples, "pe_2026"), 1),
                "coverage_quality": coverage_quality,
                "anchor_eligibility": anchor_eligibility,
                "target_price_history_status": "公开接口未系统披露目标价历史；只能用评级、每股收益和市盈率样本审计外部预期。",
                "evidence_boundary": "公开券商覆盖历史质量包只证明公开覆盖热度、样本新鲜度、评级和盈利预测区间；不替代券商全文模型、目标价历史、付费一致预期、订单、合同ASP、客户份额或单品毛利。",
                "sample_details": [
                    {
                        "date": s.get("date"),
                        "institution": s.get("institution"),
                        "rating": s.get("rating"),
                        "report_name": s.get("report_name"),
                        "eps_2026": s.get("eps_2026"),
                        "pe_2026": s.get("pe_2026"),
                        "eps_2027": s.get("eps_2027"),
                        "pe_2027": s.get("pe_2027"),
                        "eps_2028": s.get("eps_2028"),
                        "pe_2028": s.get("pe_2028"),
                        "pdf_url": s.get("pdf_url"),
                    }
                    for s in samples
                ],
            }
        )
    return rows


def public_broker_coverage_packet(valuation_rows: list[dict[str, Any]]) -> dict[str, Any]:
    rows = public_broker_coverage_rows(valuation_rows)
    return {
        "schema": "astock.public_broker_coverage_history.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "source": BROKER_RESEARCH_SNAPSHOT.get("source", "eastmoney.reportapi.report.list"),
        "rows": rows,
        "coverage": {
            "covered_tickers": len(rows),
            "public_sample_tickers": sum(1 for r in rows if r["total_sample_count"] > 0),
            "recent_sample_tickers": sum(1 for r in rows if r["recent_sample_count"] > 0),
            "multi_sample_recent_tickers": sum(1 for r in rows if r["recent_sample_count"] >= 2),
            "forecast_sample_tickers": sum(1 for r in rows if r["forecast_sample_count"] > 0),
            "stale_or_no_anchor_tickers": [r["ticker"] for r in rows if r["coverage_quality"] in {"样本陈旧", "无公开样本"}],
        },
        "use_boundary": "公开券商覆盖历史质量只用于外部锚质量审计，不替代券商全文模型、目标价历史、付费一致预期、订单、合同ASP、客户份额或单品毛利。",
    }


def public_broker_coverage_md(rows: list[dict[str, Any]]) -> str:
    packet = public_broker_coverage_packet(rows)
    table_rows = [
        [
            r["ticker"],
            r["company"],
            f"{r['total_sample_count']}/{r['recent_sample_count']}/{r['forecast_sample_count']}",
            f"{r['institution_count']}家：" + ("、".join(r["institutions"][:3]) if r["institutions"] else "无"),
            f"{r['latest_report_date']} {r['latest_institution']}",
            r["rating_mix"],
            r["eps_2026_range"],
            r["eps_2027_range"],
            r["eps_2028_range"],
            "、".join(r["forecast_years_covered"]) if r["forecast_years_covered"] else "未披露",
            r["coverage_quality"],
            r["anchor_eligibility"],
        ]
        for r in packet["rows"]
    ]
    coverage = packet["coverage"]
    return "# 公开券商覆盖历史质量\n\n门禁状态：有条件通过。本包把东方财富公开研报接口的53条样本从“最新一条摘要”升级为逐标的覆盖历史质量审计：样本总数、近三年样本、预测样本、机构数量、评级分布、2026E/2027E/2028E每股收益区间和可进入券商锚的资格。它不制造目标价；公开接口没有系统目标价历史时，目标价历史继续标记为未披露。\n\n" + md_table(
        ["代码", "名称", "样本/近三年/预测", "机构", "最新样本", "评级分布", "2026E", "2027E", "2028E", "预测年度", "质量", "估值用途"],
        table_rows,
    ) + f"\n\n- 覆盖标的：{coverage['covered_tickers']}/18\n- 有公开样本标的：{coverage['public_sample_tickers']}/18\n- 近三年样本标的：{coverage['recent_sample_tickers']}/18；近期多样本：{coverage['multi_sample_recent_tickers']}/18\n- 有盈利预测样本标的：{coverage['forecast_sample_tickers']}/18\n- 陈旧或不能进入券商锚：{','.join(coverage['stale_or_no_anchor_tickers']) if coverage['stale_or_no_anchor_tickers'] else '无'}\n- 使用边界：{packet['use_boundary']}\n"


def public_broker_coverage_pdf_rows(rows: list[dict[str, Any]]) -> list[list[Any]]:
    return [
        [
            r["ticker"],
            r["company"],
            f"{r['total_sample_count']}/{r['recent_sample_count']}/{r['institution_count']}家",
            r["latest_report_date"],
            r["eps_2026_range"],
            r["eps_2027_range"],
            r["coverage_quality"],
            r["anchor_eligibility"],
        ]
        for r in public_broker_coverage_rows(rows)
    ]


