def clean_ir_text(value: Any) -> str:
    if value is None:
        return ""
    text = str(value)
    if text.lower() == "nan":
        return ""
    return re.sub(r"\s+", " ", text).strip()


def ir_text_relevant(question: str, answer: str) -> bool:
    combined = f"{question} {answer}".upper()
    return any(k.upper() in combined for k in IR_QA_KEYWORDS)


def ir_topic_tags(question: str, answer: str) -> list[str]:
    combined = f"{question} {answer}"
    checks = [
        ("WF6/NF3", ["六氟化钨", "WF6", "NF3", "三氟化氮"]),
        ("订单/合同", ["订单", "合同", "长单", "框架", "协议", "供货"]),
        ("价格/调价", ["价格", "单价", "均价", "售价", "调价", "长协"]),
        ("客户/认证", ["客户", "认证", "台积电", "中芯", "华虹", "海力士", "长江存储", "长鑫", "ASML"]),
        ("产能/量产", ["产能", "扩产", "试生产", "投产", "量产", "产量"]),
        ("毛利/成本", ["毛利", "成本", "价差"]),
        ("高纯钨材", ["高纯钨", "钨粉", "6N", "5N"]),
        ("含氟电子材料", ["氟化液", "电子级HF", "氢氟酸", "有机氟", "四氟化硅"]),
    ]
    tags = [label for label, keys in checks if any(k in combined for k in keys)]
    return tags or ["主题相关"]


def ir_evidence_effect(question: str, answer: str) -> str:
    combined = f"{question} {answer}"
    if not answer:
        return "仅提问未回答：不能进入估值"
    denial_keys = ["不属实", "不存在", "未签署", "尚未", "不生产", "未生产", "未涉足", "没有", "未实现", "不会产生重大影响"]
    if any(k in answer for k in denial_keys):
        return "负面门禁：否证传闻或阻断业绩外推"
    if any(k in combined for k in ["价格", "单价", "均价", "调价", "长协"]):
        return "价格边界：仅作合同价格补证线索"
    if any(k in combined for k in ["客户", "认证", "批量", "稳定供应", "供货"]):
        return "客户/供货可见度补证"
    if any(k in combined for k in ["产能", "试生产", "量产", "扩产"]):
        return "产品/产能阶段补证"
    return "主题问答补证"


def ir_importance_score(question: str, answer: str) -> int:
    combined = f"{question} {answer}"
    score = 0
    for key in ["六氟化钨", "WF6", "NF3", "三氟化氮"]:
        if key in combined:
            score += 5
    for key in ["订单", "合同", "长单", "价格", "单价", "客户", "认证", "量产", "毛利"]:
        if key in combined:
            score += 2
    if answer:
        score += 2
    if any(k in answer for k in ["不属实", "未签署", "未实现", "不生产", "未生产"]):
        score += 3
    return score


def fetch_cninfo_ir_qa_rows(code: str) -> tuple[list[dict[str, Any]], str | None]:
    try:
        import akshare as ak  # noqa: PLC0415

        df = ak.stock_irm_cninfo(symbol=code)
        records = dataframe_to_records(df) if df is not None else []
    except Exception as exc:
        return [], str(exc)
    rows: list[dict[str, Any]] = []
    for record in records:
        question = clean_ir_text(record.get("问题"))
        answer = clean_ir_text(record.get("回答内容"))
        if not question:
            continue
        question_id = clean_ir_text(record.get("问题编号"))
        rows.append(
            {
                "ticker": normalize_code(record.get("股票代码") or code),
                "company": clean_ir_text(record.get("公司简称")),
                "source_platform": "巨潮互动易",
                "question": question,
                "answer": answer,
                "question_time": clean_ir_text(record.get("提问时间")),
                "answer_time": clean_ir_text(record.get("更新时间")),
                "question_id": question_id,
                "source_url": f"https://irm.cninfo.com.cn/ircs/question/questionDetail?questionId={question_id}",
            }
        )
    return rows, None


def fetch_sse_ir_qa_rows_limited(code: str, max_pages: int = 4) -> tuple[list[dict[str, Any]], str | None]:
    try:
        from bs4 import BeautifulSoup  # noqa: PLC0415
        from akshare.stock_feature.stock_sns_sseinfo import _fetch_stock_uid  # noqa: PLC0415

        probe = requests.post(
            "https://sns.sseinfo.com/allcompany.do",
            data={"code": "0", "order": "2", "areaId": "0", "page": "1"},
            timeout=8,
        )
        if probe.status_code == 403 or "Forbidden" in probe.text[:500]:
            return [], "sseinfo_403_or_non_json_response"
        uid = _fetch_stock_uid().get(code)
        if not uid:
            return [], "missing_sse_uid"
        rows: list[dict[str, Any]] = []
        for page in range(1, max_pages + 1):
            params = {
                "typeCode": "company",
                "type": "11",
                "pageSize": "100",
                "uid": uid,
                "page": str(page),
            }
            resp = requests.post("https://sns.sseinfo.com/ajax/userfeeds.do", params=params, timeout=12)
            if len(resp.text) < 300:
                break
            soup = BeautifulSoup(resp.text, features="lxml")
            content_list = [item.get_text().strip() for item in soup.find_all(name="div", attrs={"class": "m_feed_txt"})]
            date_list = [item.get_text().strip().split("\n")[0] for item in soup.find_all(name="div", attrs={"class": "m_feed_from"})]
            source_list = [
                parts[2] if len(parts := item.get_text().strip().split("\n")) > 2 else ""
                for item in soup.find_all(name="div", attrs={"class": "m_feed_from"})
            ]
            for idx in range(0, len(content_list), 2):
                raw_question = content_list[idx]
                raw_answer = content_list[idx + 1] if idx + 1 < len(content_list) else ""
                question = clean_ir_text(raw_question.split(")", 1)[1] if ")" in raw_question else raw_question)
                answer = clean_ir_text(raw_answer)
                rows.append(
                    {
                        "ticker": code,
                        "company": "",
                        "source_platform": "上证e互动",
                        "question": question,
                        "answer": answer,
                        "question_time": clean_ir_text(date_list[idx] if idx < len(date_list) else ""),
                        "answer_time": clean_ir_text(date_list[idx + 1] if idx + 1 < len(date_list) else ""),
                        "question_id": f"sse-{uid}-{page}-{idx}",
                        "question_source": clean_ir_text(source_list[idx] if idx < len(source_list) else ""),
                        "answer_source": clean_ir_text(source_list[idx + 1] if idx + 1 < len(source_list) else ""),
                        "source_url": f"https://sns.sseinfo.com/company.do?uid={uid}",
                    }
                )
        return rows, None
    except Exception as exc:
        message = str(exc)
        if "Expecting value" in message:
            message = "sseinfo_403_or_non_json_response"
        return [], message


def investor_relations_qa_complete(packet: dict[str, Any]) -> bool:
    summaries = packet.get("ticker_summaries", [])
    summary_codes = {str(r.get("ticker")) for r in summaries}
    required = {t["code"] for t in TICKERS}
    if not required <= summary_codes:
        return False
    if packet.get("source_tickers", 0) < 8 or packet.get("relevant_tickers", 0) < 8 or packet.get("high_impact_rows", 0) < 15:
        return False
    row_required = ["ticker", "company", "source_platform", "question", "answer_status", "topic_tags", "evidence_effect", "valuation_use", "evidence_boundary"]
    for row in packet.get("rows", []):
        for key in row_required:
            if row.get(key) in (None, "", []):
                return False
    return True


def fetch_investor_relations_qa_snapshot(rows: list[dict[str, Any]]) -> dict[str, Any]:
    cache_path = CASE / "data/investor_relations_qa_evidence.json"
    if os.getenv("ASTOCK_REFRESH_IR_QA") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if cached.get("schema") == "astock.investor_relations_qa_evidence.v1" and investor_relations_qa_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass
    by_code = {r["code"]: r for r in rows}
    all_raw: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        fetched, error = fetch_cninfo_ir_qa_rows(code) if code.startswith(("0", "3")) else fetch_sse_ir_qa_rows_limited(code)
        if error:
            errors.append({"ticker": code, "company": ticker["name"], "error": error})
        for item in fetched:
            item["ticker"] = code
            item["company"] = ticker["name"]
            all_raw.append(item)
    raw_by_code: dict[str, list[dict[str, Any]]] = {}
    for row in all_raw:
        raw_by_code.setdefault(row["ticker"], []).append(row)
    evidence_rows: list[dict[str, Any]] = []
    summaries: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        relevant_rows: list[dict[str, Any]] = []
        for row in raw_by_code.get(code, []):
            question = clean_ir_text(row.get("question"))
            answer = clean_ir_text(row.get("answer"))
            if not ir_text_relevant(question, answer):
                continue
            tags = ir_topic_tags(question, answer)
            effect = ir_evidence_effect(question, answer)
            score = ir_importance_score(question, answer)
            relevant_rows.append(
                {
                    "ticker": code,
                    "company": by_code.get(code, {}).get("name", row.get("company", "")),
                    "source_platform": row.get("source_platform", ""),
                    "question_time": row.get("question_time", ""),
                    "answer_time": row.get("answer_time", ""),
                    "question": question,
                    "answer": answer or "未回复",
                    "answer_status": "已回复" if answer else "未回复",
                    "topic_tags": tags,
                    "evidence_effect": effect,
                    "importance_score": score,
                    "source_url": row.get("source_url", ""),
                    "valuation_use": "只用于P0/P1缺口补证、传闻否证、调研优先级和风险折扣；不得直接进入增长每股收益或基本面目标价上修。",
                    "evidence_boundary": "互动问答属于公司公开沟通口径，未披露具体订单金额、合同平均售价、收入确认比例、客户份额或单品毛利时，不得替代这些硬字段。",
                }
            )
        relevant_rows.sort(key=lambda x: (x["importance_score"], x.get("answer_time", "")), reverse=True)
        selected = relevant_rows[:8]
        evidence_rows.extend(selected)
        summaries.append(
            {
                "ticker": code,
                "company": by_code.get(code, {}).get("name", ""),
                "source_platform": "巨潮互动易" if code.startswith(("0", "3")) else "上证e互动",
                "raw_question_count": len(raw_by_code.get(code, [])),
                "relevant_question_count": len(relevant_rows),
                "selected_evidence_count": len(selected),
                "answered_relevant_count": len([r for r in relevant_rows if r["answer_status"] == "已回复"]),
                "top_evidence_effect": selected[0]["evidence_effect"] if selected else "未找到主题相关互动问答",
                "top_topic_tags": "；".join(selected[0]["topic_tags"]) if selected else "未找到",
            }
        )
    evidence_rows.sort(key=lambda x: (x["importance_score"], x.get("answer_time", "")), reverse=True)
    return {
        "schema": "astock.investor_relations_qa_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "covered_tickers": len(TICKERS),
        "source_tickers": len([x for x in summaries if x["raw_question_count"] > 0]),
        "relevant_tickers": len([x for x in summaries if x["relevant_question_count"] > 0]),
        "selected_rows": len(evidence_rows),
        "high_impact_rows": len([x for x in evidence_rows if x.get("importance_score", 0) >= 7]),
        "ticker_summaries": summaries,
        "rows": evidence_rows,
        "errors": errors,
        "source": "cninfo_irm_and_sseinfo_public_investor_qa",
        "use_boundary": "互动问答只用于公司口径补证、传闻否证、调研优先级和风险折扣；未披露具体订单金额、合同平均售价、收入确认比例、客户份额或单品毛利时，不得替代这些硬字段，也不得直接上调基本面目标价。",
    }


def investor_relations_qa_pdf_rows(limit: int = 12) -> list[list[Any]]:
    sorted_rows = sorted(INVESTOR_RELATIONS_QA_SNAPSHOT.get("rows", []), key=lambda x: (x.get("importance_score", 0), x.get("answer_time", "")), reverse=True)
    return [
        [
            r["ticker"],
            r["company"],
            "；".join(r.get("topic_tags", [])),
            r.get("evidence_effect", ""),
            compact_reader_text(r.get("question"), 42),
            compact_reader_text(r.get("answer"), 58),
        ]
        for r in sorted_rows[:limit]
    ]


