def ir_activity_record_md() -> str:
    rows = IR_ACTIVITY_RECORD_SNAPSHOT.get("rows", [])
    summaries = IR_ACTIVITY_RECORD_SNAPSHOT.get("ticker_summaries", [])
    content_rows = IR_ACTIVITY_RECORD_SNAPSHOT.get("content_probe_rows", [])
    evidence_table = [
        [
            r["ticker"],
            r["company"],
            r["source_platform"],
            r["announcement_date"],
            r["activity_type"],
            compact_reader_text(r["announcement_title"], 96),
            r["content_parse_status"],
            r["p0_field_status"],
            r["valuation_use"],
        ]
        for r in rows
    ]
    summary_table = [
        [
            r["ticker"],
            r["company"],
            r["cninfo_relation_records"],
            r["eastmoney_ir_titles"],
            r["selected_evidence_count"],
            r.get("content_probe_count", 0),
            r["latest_activity_date"],
            r["source_depth"],
            r["p0_field_status"],
            r["next_action"],
        ]
        for r in summaries
    ]
    content_table = [
        [
            r["ticker"],
            r["company"],
            r["announcement_date"],
            r["activity_type"],
            "；".join(r.get("matched_field_groups", [])),
            r["p0_disclosure_status"],
            compact_reader_text("；".join(r.get("snippets", [])), 140),
            r["valuation_use"],
        ]
        for r in content_rows
    ]
    errors = IR_ACTIVITY_RECORD_SNAPSHOT.get("errors", [])
    err_text = "无" if not errors else "；".join(f"{e.get('ticker')}:{e.get('source')}:{e.get('error')}" for e in errors[-10:])
    return "# 投关调研记录标题索引与正文关键词探针补证\n\n门禁状态：有条件通过。本包抓取巨潮投关专栏和东方财富公告索引，筛选投资者关系活动记录表、投资者关系管理信息、机构调研、业绩说明会和投资者网上接待日标题，并对东方财富可取正文的记录执行关键词探针。它补强“调研纪要层已查”、正文语境和后续人工复核优先级，但仍不能自动关闭P0缺口：未人工复核正文、未披露订单金额、合同平均售价、收入确认比例、客户份额或单品毛利时，不得进入增长每股收益或基本面目标价上修。\n\n" + md_table(
        ["代码", "名称", "来源", "日期", "类型", "标题", "正文状态", "P0字段状态", "估值用途"],
        evidence_table,
    ) + "\n\n## 覆盖摘要\n\n" + md_table(
        ["代码", "名称", "巨潮记录", "东方财富标题", "入选证据", "正文探针", "最近日期", "来源深度", "P0状态", "下一步"],
        summary_table,
    ) + "\n\n## 正文关键词探针\n\n" + md_table(
        ["代码", "名称", "日期", "类型", "命中字段组", "P0状态", "正文摘录", "估值用途"],
        content_table,
    ) + f"\n\n- 覆盖标的：{IR_ACTIVITY_RECORD_SNAPSHOT.get('covered_tickers', 0)}/18\n- 标题来源覆盖：{IR_ACTIVITY_RECORD_SNAPSHOT.get('title_source_tickers', 0)}/18\n- 巨潮投关专栏覆盖：{IR_ACTIVITY_RECORD_SNAPSHOT.get('cninfo_relation_tickers', 0)}/18\n- 入选证据：{IR_ACTIVITY_RECORD_SNAPSHOT.get('selected_rows', 0)}条\n- 正文探针覆盖：{IR_ACTIVITY_RECORD_SNAPSHOT.get('content_probe_tickers', 0)}/18，记录{IR_ACTIVITY_RECORD_SNAPSHOT.get('content_probe_records', 0)}条，关键词命中{IR_ACTIVITY_RECORD_SNAPSHOT.get('content_probe_keyword_hits', 0)}组\n- 需人工复核P0候选：{IR_ACTIVITY_RECORD_SNAPSHOT.get('p0_candidate_rows', 0)}条\n- P0关闭数量：{IR_ACTIVITY_RECORD_SNAPSHOT.get('p0_closed_count', 0)}\n- 抓取/解析错误：{err_text}\n- 使用边界：{IR_ACTIVITY_RECORD_SNAPSHOT.get('use_boundary', '')}\n"


CONTRACT_ORDER_TITLE_KEYWORDS = [
    "重大合同",
    "合同",
    "中标",
    "定点",
    "供货",
    "供气合同",
    "供应协议",
    "采购协议",
    "销售合同",
    "长期协议",
    "长单",
    "批量供货",
    "客户订单",
    "订单",
    "框架协议",
    "战略合作",
    "合作协议",
    "项目合同",
]

CONTRACT_ORDER_EXCLUDE_KEYWORDS = ["劳动合同", "独立董事", "保荐协议", "募集资金", "回购", "担保", "借款合同", "租赁合同"]

CONTRACT_ORDER_CONTENT_GROUPS: list[tuple[str, list[str]]] = [
    ("合同/订单", ["合同金额", "合同总额", "销售金额", "采购金额", "订单", "合同", "长单", "框架协议", "供货", "供气合同", "合作协议"]),
    ("价格/定价", ["单价", "均价", "结算价格", "价格调整", "定价", "市场公允", "报价", "价格"]),
    ("产品/主题", ["六氟化钨", "三氟化氮", "电子特气", "电子级", "氟化液", "电解液", "高纯钨", "钨粉", "氟化氢", "HF", "氯化氢", "HCL", "氘气", "D2", "氧气", "氮气", "丙烷"]),
    ("客户/交易对手", ["客户", "交易对手", "宁德时代", "湖北鼎益", "马坑矿业", "巨化股份", "巨化集团", "关联方"]),
    ("期限/交付", ["期限", "有效期", "交货", "交付", "供气条件", "正式供气", "2028", "十年", "结算"]),
    ("会计/风险", ["收入确认", "经营业绩", "审计确认", "不确定性", "无法全面履行", "风险"]),
]


def contract_order_title_relevant(title: str) -> bool:
    text = clean_ir_text(title)
    if not text:
        return False
    if any(k in text for k in CONTRACT_ORDER_EXCLUDE_KEYWORDS):
        return False
    return any(k in text for k in CONTRACT_ORDER_TITLE_KEYWORDS)


def contract_order_type(title: str) -> str:
    text = clean_ir_text(title)
    if "中标" in text:
        return "中标/定点公告"
    if "供气合同" in text:
        return "供气合同"
    if "合作协议" in text or "框架协议" in text or "战略合作" in text:
        return "合作/框架协议"
    if "合同" in text:
        return "合同公告"
    if "订单" in text or "长单" in text:
        return "订单/长单线索"
    return "合同/订单相关公告"


def fetch_eastmoney_contract_order_rows(code: str, max_pages: int = 5) -> tuple[list[dict[str, Any]], str | None, int]:
    params = {
        "sr": "-1",
        "page_size": "100",
        "page_index": "1",
        "ann_type": "A",
        "client_source": "web",
        "f_node": "0",
        "s_node": "0",
        "begin_time": "2024-01-01",
        "end_time": "2026-06-29",
        "stock_list": code,
    }
    headers = {"User-Agent": "Mozilla/5.0", "Referer": "https://data.eastmoney.com/notices/"}
    try:
        response = requests.get("https://np-anotice-stock.eastmoney.com/api/security/ann", params=params, headers=headers, timeout=(5, 15))
        response.raise_for_status()
        data = response.json().get("data") or {}
        total = int(data.get("total_hits") or 0)
        pages = max(1, min(max_pages, math.ceil(total / 100) if total else 1))
    except Exception as exc:
        return [], str(exc), 0
    rows: list[dict[str, Any]] = []
    try:
        for page in range(1, pages + 1):
            params["page_index"] = str(page)
            if page == 1:
                page_data = data
            else:
                resp = requests.get("https://np-anotice-stock.eastmoney.com/api/security/ann", params=params, headers=headers, timeout=(5, 15))
                resp.raise_for_status()
                page_data = resp.json().get("data") or {}
            for item in page_data.get("list") or []:
                title = clean_ir_text(item.get("title") or item.get("title_ch"))
                if not contract_order_title_relevant(title):
                    continue
                codes = item.get("codes") or []
                code_item = next((x for x in codes if str(x.get("stock_code")) == code), codes[0] if codes else {})
                art_code = clean_ir_text(item.get("art_code"))
                rows.append(
                    {
                        "ticker": normalize_code(code_item.get("stock_code") or code),
                        "company": clean_ir_text(code_item.get("short_name")),
                        "source_platform": "东方财富公告索引",
                        "announcement_date": eastmoney_notice_date(item.get("notice_date")),
                        "announcement_title": title,
                        "announcement_url": eastmoney_notice_url(code, art_code),
                        "announcement_type": contract_order_type(title),
                        "art_code": art_code,
                    }
                )
    except Exception as exc:
        return rows, str(exc), total
    return rows, None, total


def classify_contract_order_scope(content: str) -> str:
    direct_contract = bool(
        re.search(r"(六氟化钨|三氟化氮|WF6|NF3)[^。；]{0,100}(销售合同|采购合同|合同金额|合计)", content)
        or re.search(r"(销售合同|采购合同|合同金额|合计)[^。；]{0,100}(六氟化钨|三氟化氮|WF6|NF3)", content)
    )
    electronic_gas_platform_contract = bool(
        ("集成电路客户" in content or "客户 A" in content or "客户A" in content)
        and ("氟化氢" in content or "HF" in content)
        and ("氯化氢" in content or "HCL" in content)
        and ("氘气" in content or "D2" in content)
        and ("采购合同" in content or "销售合同" in content or "合同金额" in content)
    )
    if direct_contract:
        return "WF6/NF3正式合同，订单金额已披露但平均售价/毛利未披露"
    if electronic_gas_platform_contract:
        return "电子气体平台合同，披露金额但不等同WF6/NF3单品订单"
    if ("供应氧气" in content and "氮气" in content) or ("氧气、氮气、丙烷" in content):
        return "工业现场制气合同，不等同WF6/NF3订单"
    if ("六氟化钨" in content or "三氟化氮" in content or "电子特气" in content or "电子级" in content) and "供气合同" not in content[:3000]:
        return "主题相关，需要人工复核是否为电子特气/电子材料单品"
    if "电解液" in content or "宁德时代" in content:
        return "锂电电解液协议，不等同电子特气订单"
    if "钼精矿" in content or "稀土" in content:
        return "原料/关联交易框架，不等同半导体高纯钨材订单"
    return "合同/订单公告，主题相关性需人工复核"


def contract_order_p0_status(content: str, scope: str) -> tuple[str, bool]:
    has_amount = bool(re.search(r"(合同金额|合同总额|销售金额|采购金额|预计金额)[^。；，]{0,50}(亿元|万元|人民币|\d)", content))
    has_price = any(k in content for k in ["单价", "销售均价", "合同价格", "结算价格", "价格调整"])
    has_term = any(k in content for k in ["有效期", "履行期限", "十年", "2028 年", "2028年"])
    has_not_disclosed = any(k in content for k in ["以双方书面确认的订单", "另行约定", "不予公开披露", "具体单价涉及商业敏感信息"])
    theme_exact = "WF6/NF3正式合同" in scope or "电子特气" in scope or "电子材料" in scope
    if has_amount and "WF6/NF3正式合同" in scope:
        return "披露WF6/NF3合同金额和匿名集成电路客户；订单金额部分补证，但平均售价/确认比例/毛利未关闭", False
    if has_amount and "电子气体平台合同" in scope:
        return "披露电子气体平台合同金额和匿名集成电路客户；补强平台订单可见度，但不关闭WF6/NF3单品均价/毛利", False
    if has_amount and "工业现场制气" in scope:
        return "披露合同金额和期限，但产品为工业现场制气；不关闭WF6/电子特气P0", False
    if has_amount and theme_exact and not has_not_disclosed:
        return "出现主题相关合同金额，需人工复核后才可判断是否关闭P0", False
    if has_price or has_term:
        return "披露定价/期限/订单框架线索，但未给可入模单品金额、均价或毛利", False
    return "未发现可直接入模的合同金额、单品价格、收入确认比例或毛利字段", False


def build_contract_order_content_probe(row: dict[str, Any], content: str, attach_url: str = "") -> dict[str, Any]:
    matched_groups: list[str] = []
    snippets: list[str] = []
    for group, keywords in CONTRACT_ORDER_CONTENT_GROUPS:
        group_snippets = keyword_snippets(content, keywords, limit=2)
        if group_snippets:
            matched_groups.append(group)
            snippets.extend(group_snippets[:2])
    scope = classify_contract_order_scope(content)
    p0_status, p0_closed = contract_order_p0_status(content, scope)
    p0_order_amount_closed = "WF6/NF3正式合同" in scope and "披露WF6/NF3合同金额" in p0_status
    platform_order_amount_evidence = "电子气体平台合同" in scope and "披露电子气体平台合同金额" in p0_status
    valuation_use = "只用于官方合同/中标/供货协议层来源穷尽和订单可见度分层；除非公告明确披露主题单品订单金额、合同平均售价、收入确认比例、客户份额和单品毛利，否则不得进入增长每股收益或基本面目标价上修。"
    if p0_order_amount_closed:
        valuation_use = "可作为WF6/NF3主题单品订单金额的历史官方样本，用于事件验证和收入桥约束；但缺少合同平均售价、收入确认比例、客户份额和单品毛利前，不得直接上修长期增长每股收益或基本面目标价。"
    if platform_order_amount_evidence:
        valuation_use = "可作为中船特气电子气体平台订单金额样本，用于提高平台订单可见度；但产品为HF/HCL/D2等多品类合同，不替代WF6/NF3单品订单、合同平均售价、收入确认比例或单品毛利。"
    return {
        "ticker": row.get("ticker", ""),
        "company": row.get("company", ""),
        "announcement_date": row.get("announcement_date", ""),
        "announcement_type": row.get("announcement_type", ""),
        "announcement_title": row.get("announcement_title", ""),
        "source_platform": row.get("source_platform", ""),
        "art_code": row.get("art_code", ""),
        "announcement_url": row.get("announcement_url", ""),
        "attach_url": attach_url,
        "content_char_count": len(content),
        "matched_field_groups": matched_groups or ["未命中合同字段"],
        "contract_scope": scope,
        "snippet_count": len(snippets[:5]),
        "snippets": snippets[:5] or ["未在正文中命中合同金额、价格、客户、期限或收入确认关键词"],
        "p0_disclosure_status": p0_status,
        "p0_closed": p0_closed,
        "p0_order_amount_closed": p0_order_amount_closed,
        "platform_order_amount_evidence": platform_order_amount_evidence,
        "valuation_use": valuation_use,
        "evidence_boundary": "合同公告命中仍需核验产品范围；工业气体、原料采购、关联交易或锂电协议不得替代WF6/NF3/电子材料单品订单。",
    }


def normalize_contract_order_announcement_snapshot(packet: dict[str, Any]) -> dict[str, Any]:
    for row in packet.get("rows", []):
        context = "；".join(
            [
                str(row.get("announcement_title", "")),
                str(row.get("contract_scope", "")),
                str(row.get("p0_disclosure_status", "")),
                "；".join(str(x) for x in row.get("snippets", [])),
            ]
        )
        if (
            ("集成电路客户" in context or "客户 A" in context or "客户A" in context)
            and ("氟化氢" in context or "HF" in context)
            and ("氯化氢" in context or "HCL" in context)
            and ("氘气" in context or "D2" in context)
            and ("148,216,408" in context or "148216408" in context or "1.4822" in context)
        ):
            row["contract_scope"] = "电子气体平台合同，披露金额但不等同WF6/NF3单品订单"
            row["p0_disclosure_status"] = "披露电子气体平台合同金额和匿名集成电路客户；补强平台订单可见度，但不关闭WF6/NF3单品均价/毛利"
            row["platform_order_amount_evidence"] = True
            row["valuation_use"] = "可作为中船特气电子气体平台订单金额样本，用于提高平台订单可见度；但产品为HF/HCL/D2等多品类合同，不替代WF6/NF3单品订单、合同平均售价、收入确认比例或单品毛利。"
        else:
            row.setdefault("platform_order_amount_evidence", False)
    packet["platform_order_amount_rows"] = sum(1 for row in packet.get("rows", []) if row.get("platform_order_amount_evidence"))
    packet["use_boundary"] = "合同/中标/供货协议公告扫描只证明官方公告层是否存在合同金额、期限、定价或订单线索；中船特气WF6/NF3历史合同可作为主题单品订单金额样本，中船特气HF/HCL/D2等11种产品合同只补强电子气体平台订单可见度，均不替代合同平均售价、收入确认比例、客户份额或单品毛利；工业气体、原料采购、关联交易和锂电协议不得替代WF6/NF3/电子材料单品订单。"
    return packet


def contract_order_announcement_packet_complete(packet: dict[str, Any]) -> bool:
    if packet.get("schema") != "astock.contract_order_announcement_evidence.v1":
        return False
    if packet.get("errors"):
        return False
    if packet.get("covered_tickers") != len(TICKERS) or packet.get("matched_tickers", 0) < 1:
        return False
    required = ["ticker", "company", "announcement_date", "announcement_title", "announcement_type", "contract_scope", "p0_disclosure_status", "p0_order_amount_closed", "valuation_use", "evidence_boundary"]
    for row in packet.get("rows", []):
        for key in required:
            if row.get(key) in (None, "", []):
                return False
    return True


def fetch_contract_order_announcement_snapshot(rows: list[dict[str, Any]]) -> dict[str, Any]:
    cache_path = CASE / "data/contract_order_announcement_evidence.json"
    if os.getenv("ASTOCK_REFRESH_CONTRACT_ANNOUNCEMENTS") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            cached = normalize_contract_order_announcement_snapshot(cached)
            if contract_order_announcement_packet_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass
    by_code = {r["code"]: r for r in rows}
    evidence_rows: list[dict[str, Any]] = []
    summaries: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        raw_rows, fetch_error, total = fetch_eastmoney_contract_order_rows(code)
        if fetch_error:
            errors.append({"ticker": code, "company": ticker["name"], "source": "eastmoney_contract_order_index", "error": fetch_error})
        selected = raw_rows[:5]
        parsed_count = 0
        for selected_row in selected:
            art_code = selected_row.get("art_code")
            content_packet, content_error = fetch_eastmoney_notice_content(art_code)
            if content_error or not content_packet:
                errors.append({"ticker": code, "company": ticker["name"], "source": "eastmoney_contract_order_content", "art_code": art_code, "error": content_error or "empty_content_packet"})
                continue
            evidence_rows.append(build_contract_order_content_probe(selected_row, content_packet["notice_content"], content_packet.get("attach_url", "")))
            parsed_count += 1
        summaries.append(
            {
                "ticker": code,
                "company": by_code.get(code, {}).get("name", ticker["name"]),
                "total_announcements": total,
                "matched_contract_order_titles": len(raw_rows),
                "parsed_contract_order_records": parsed_count,
                "latest_contract_order_date": selected[0]["announcement_date"] if selected else "未找到",
                "p0_closure_status": "未关闭",
                "next_action": "若出现主题相关合同公告，人工复核产品范围、金额、价格、交付和收入确认口径",
            }
        )
    evidence_rows.sort(key=lambda x: (x.get("announcement_date", ""), x.get("ticker", "")), reverse=True)
    amount_rows = [r for r in evidence_rows if "合同金额" in "；".join(r.get("snippets", [])) or "亿元" in "；".join(r.get("snippets", []))]
    theme_order_amount_rows = [r for r in evidence_rows if r.get("p0_order_amount_closed")]
    packet = {
        "schema": "astock.contract_order_announcement_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "covered_tickers": len(TICKERS),
        "matched_tickers": len({r["ticker"] for r in evidence_rows}),
        "selected_rows": len(evidence_rows),
        "amount_disclosure_rows": len(amount_rows),
        "theme_order_amount_rows": len(theme_order_amount_rows),
        "p0_closed_count": 0,
        "ticker_summaries": summaries,
        "rows": evidence_rows,
        "errors": errors,
        "source": "eastmoney_notice_index_and_content_api",
        "use_boundary": "合同/中标/供货协议公告扫描只证明官方公告层是否存在合同金额、期限、定价或订单线索；中船特气WF6/NF3历史合同可作为主题单品订单金额样本，中船特气HF/HCL/D2等11种产品合同只补强电子气体平台订单可见度，均不替代合同平均售价、收入确认比例、客户份额或单品毛利；工业气体、原料采购、关联交易和锂电协议不得替代WF6/NF3/电子材料单品订单。",
    }
    return normalize_contract_order_announcement_snapshot(packet)


def contract_order_announcement_pdf_rows(limit: int = 8) -> list[list[Any]]:
    def contract_order_priority(row: dict[str, Any]) -> int:
        scope = str(row.get("contract_scope", ""))
        if row.get("p0_order_amount_closed"):
            return 0
        if row.get("platform_order_amount_evidence") or "电子气体平台合同" in scope:
            return 1
        if "主题相关" in scope:
            return 2
        if "工业现场制气" in scope:
            return 4
        if "锂电电解液" in scope or "原料/关联交易" in scope:
            return 5
        return 3

    sorted_rows = sorted(
        CONTRACT_ORDER_ANNOUNCEMENT_SNAPSHOT.get("rows", []),
        key=lambda r: (contract_order_priority(r), r.get("ticker", ""), r.get("announcement_date", "")),
    )
    return [
        [
            r["ticker"],
            r["company"],
            r.get("announcement_date", ""),
            r.get("announcement_type", ""),
            compact_reader_text(r.get("announcement_title"), 50),
            compact_reader_text(r.get("contract_scope"), 40),
            compact_reader_text(r.get("p0_disclosure_status"), 42),
        ]
        for r in sorted_rows[:limit]
    ]


