def regulatory_inquiry_md() -> str:
    rows = REGULATORY_INQUIRY_SNAPSHOT.get("rows", [])
    summaries = REGULATORY_INQUIRY_SNAPSHOT.get("ticker_summaries", [])
    evidence_table = [
        [
            r["ticker"],
            r["company"],
            r["announcement_date"],
            r["inquiry_type"],
            compact_reader_text(r["announcement_title"], 96),
            "；".join(r.get("matched_field_groups", [])),
            r["field_status"],
            compact_reader_text("；".join(r.get("snippets", [])), 160),
            r["valuation_use"],
        ]
        for r in rows
    ]
    summary_table = [
        [
            r["ticker"],
            r["company"],
            r["total_announcements"],
            r["matched_inquiry_titles"],
            r["parsed_inquiry_records"],
            r["latest_inquiry_date"],
            r["latest_inquiry_type"],
            r["evidence_status"],
            r["valuation_use"],
        ]
        for r in summaries
    ]
    errors = REGULATORY_INQUIRY_SNAPSHOT.get("errors", [])
    err_text = "无" if not errors else "；".join(f"{e.get('ticker')}:{e.get('source')}:{e.get('error')}" for e in errors[-10:])
    return "# 问询/审核回复公告证据\n\n门禁状态：有条件通过。本包扫描2020年1月1日至" + PUBLIC_SOURCE_CUTOFF_CN + "东方财富公告索引中的问询函、审核问询回复、反馈意见、监管函、关注函和落实函相关公告，并抓取可得正文。它用于回答“交易所或监管问询层是否已经披露产品收入、客户订单、合同平均售价、收入确认、单品毛利或募投产能硬字段”，不能把问询标题或泛化回复直接替代单品订单、合同平均售价、收入确认比例、客户份额、单品收入或单品毛利。\n\n" + md_table(
        ["代码", "名称", "日期", "类型", "标题", "命中字段组", "硬字段状态", "正文短摘", "估值用途"],
        evidence_table,
    ) + "\n\n## 覆盖摘要\n\n" + md_table(
        ["代码", "名称", "总公告", "问询标题", "正文解析", "最新日期", "最新类型", "证据状态", "估值用途"],
        summary_table,
    ) + f"\n\n- 覆盖标的：{REGULATORY_INQUIRY_SNAPSHOT.get('covered_tickers', 0)}/18\n- 命中问询/审核回复标的：{REGULATORY_INQUIRY_SNAPSHOT.get('matched_tickers', 0)}/18\n- 正文解析标的：{REGULATORY_INQUIRY_SNAPSHOT.get('parsed_tickers', 0)}/18\n- 入选证据：{REGULATORY_INQUIRY_SNAPSHOT.get('selected_rows', 0)}条\n- 抓取/解析错误：{err_text}\n- 使用边界：{REGULATORY_INQUIRY_SNAPSHOT.get('use_boundary', '')}\n"


def contract_tax_basis(row: dict[str, Any]) -> str:
    joined = row.get("announcement_title", "") + "；" + "；".join(str(x) for x in row.get("snippets", []))
    if "不含税" in joined:
        return "不含税"
    if "含税" in joined:
        return "含税"
    return "未注明"


def contract_product_label(row: dict[str, Any]) -> str:
    detail = row.get("announcement_title", "") + "；" + "；".join(str(x) for x in row.get("snippets", []))
    scope = row.get("contract_scope", "")
    if "六氟化钨" in detail or "WF6" in detail:
        return "六氟化钨/WF6"
    if "三氟化氮" in detail or "NF3" in detail:
        return "三氟化氮/NF3"
    if ("氟化氢" in detail or "HF" in detail) and ("氯化氢" in detail or "HCL" in detail):
        return "HF/HCL/D2等电子气体平台"
    if "WF6/NF3" in scope:
        return "WF6/NF3主题合同"
    if "电子气体平台" in scope:
        return "电子气体平台合同"
    return "非主题合同"


def cssc_segment_denominators() -> dict[str, float | None]:
    company_revenue: float | None = None
    electronic_segment_revenue: float | None = None
    triflate_revenue: float | None = None
    for row in BUSINESS_SEGMENT_SNAPSHOT.get("rows", []):
        if row.get("ticker") != "688146":
            continue
        revenue = safe_float_value(row.get("revenue"))
        if revenue is not None:
            company_revenue = (company_revenue or 0.0) + revenue
        if row.get("segment") == "电子特种气体":
            electronic_segment_revenue = revenue
        if row.get("segment") == "三氟甲磺酸系列":
            triflate_revenue = revenue
    if company_revenue in (None, 0):
        for row in OFFICIAL_SEGMENT_TABLE_SNAPSHOT.get("rows", []):
            if row.get("ticker") == "688146":
                revenue = safe_float_value(row.get("revenue"))
                company_revenue = (company_revenue or 0.0) + (revenue or 0.0)
                if row.get("segment") == "电子特种气体":
                    electronic_segment_revenue = revenue
                if row.get("segment") == "三氟甲磺酸系列":
                    triflate_revenue = revenue
    return {
        "company_revenue": company_revenue,
        "electronic_segment_revenue": electronic_segment_revenue,
        "triflate_revenue": triflate_revenue,
    }


def contract_economics_constraint_rows() -> list[dict[str, Any]]:
    denominators = cssc_segment_denominators()
    company_revenue = denominators.get("company_revenue")
    electronic_segment_revenue = denominators.get("electronic_segment_revenue")
    rows: list[dict[str, Any]] = []
    for row in CONTRACT_ORDER_ANNOUNCEMENT_SNAPSHOT.get("rows", []):
        if row.get("ticker") != "688146":
            continue
        if not (row.get("p0_order_amount_closed") or row.get("platform_order_amount_evidence")):
            continue
        amount = contract_yuan_amount(row)
        if amount is None:
            continue
        tax_basis = contract_tax_basis(row)
        product = contract_product_label(row)
        company_ratio = amount / company_revenue if company_revenue else None
        electronic_ratio = amount / electronic_segment_revenue if electronic_segment_revenue else None
        if row.get("p0_order_amount_closed"):
            evidence_grade = "主题单品订单金额部分补证"
            model_use = "可用于中船特气WF6/NF3历史单笔订单金额强度、事件验证和收入上限约束；不得直接上修长期增长每股收益。"
        else:
            evidence_grade = "电子气体平台订单金额补证"
            model_use = "可用于中船特气电子气体平台订单可见度；不得替代WF6/NF3单品订单或盈利。"
        if tax_basis == "含税":
            ratio_note = "合同金额含税，和收入口径不可直接同口径比较；比例只能作为上限观察。"
        elif tax_basis == "不含税":
            ratio_note = "合同金额不含税，可与收入口径做粗略强度比较，但仍缺交付和确认节奏。"
        else:
            ratio_note = "税口径未注明，比例仅作弱观察。"
        rows.append(
            {
                "ticker": row.get("ticker", ""),
                "company": row.get("company", ""),
                "announcement_date": row.get("announcement_date", ""),
                "product_scope": product,
                "amount_yuan": amount,
                "amount_cny_yi": amount / 1e8,
                "tax_basis": tax_basis,
                "company_revenue_2025": company_revenue,
                "electronic_segment_revenue_2025": electronic_segment_revenue,
                "amount_to_company_revenue": company_ratio,
                "amount_to_electronic_segment_revenue": electronic_ratio,
                "customer_description": "境内某知名集成电路客户A",
                "evidence_grade": evidence_grade,
                "model_use": model_use,
                "blocked_fields": "合同ASP、销量/单价拆分、交付节奏、收入确认比例、客户份额、单品毛利",
                "ratio_note": ratio_note,
                "source_artifact": "data/contract_order_announcement_evidence.json/md",
                "announcement_url": row.get("announcement_url", ""),
                "evidence_boundary": "合同金额只能说明历史订单强度；缺少ASP、收入确认比例、客户份额和单品毛利前，不得把金额等同于增长EPS或基本面目标价上修。",
            }
        )
    rows.sort(key=lambda r: (r["announcement_date"], r["product_scope"]), reverse=True)
    return rows


def contract_economics_constraint_packet() -> dict[str, Any]:
    rows = contract_economics_constraint_rows()
    theme_rows = [r for r in rows if "主题单品" in r["evidence_grade"]]
    platform_rows = [r for r in rows if "平台" in r["evidence_grade"]]
    return {
        "schema": "astock.contract_economics_constraint.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "company": "中船特气",
        "ticker": "688146",
        "sample_rows": len(rows),
        "theme_single_product_order_rows": len(theme_rows),
        "platform_order_rows": len(platform_rows),
        "amount_sum_yuan": sum(float(r["amount_yuan"]) for r in rows),
        "theme_amount_sum_yuan": sum(float(r["amount_yuan"]) for r in theme_rows),
        "p0_economics_closed_count": 0,
        "rows": rows,
        "use_boundary": "合同金额经济性约束把中船特气已披露合同金额与2025年公司收入和电子特气分部收入做比例桥；它只能约束历史订单强度和收入上限，不关闭合同ASP、销量、收入确认比例、客户份额或单品毛利。",
    }


