def parse_iso_date(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.strptime(text[:10], "%Y-%m-%d")
    except ValueError:
        return None


def days_to_date(date_text: Any, base_text: str = PUBLIC_SOURCE_CUTOFF) -> int | None:
    target = parse_iso_date(date_text)
    base = parse_iso_date(base_text)
    if not target or not base:
        return None
    return (target - base).days


def disclosure_status_cn(row: dict[str, Any]) -> str:
    actual = str(row.get("ACTUAL_PUBLISH_DATE") or row.get("actual_publish_date") or "").strip()
    is_publish = str(row.get("IS_PUBLISH") or row.get("is_published") or "").strip()
    if actual or is_publish in {"1", "已披露", "true", "True"}:
        return "已披露"
    return "待披露"


def disclosure_report_label(row: dict[str, Any]) -> str:
    label = clean_ir_text(row.get("REPORT_TYPE_NAME") or row.get("report_type_name"))
    if label:
        return label
    code = str(row.get("REPORT_TYPE") or row.get("report_type") or "").strip()
    mapping = {
        "1": "2026年 一季报",
        "2": "2026年 半年报",
        "3": "2026年 三季报",
        "4": "2026年 年报",
    }
    return mapping.get(code, "未知报告")


def fetch_eastmoney_disclosure_calendar_rows(code: str) -> tuple[list[dict[str, Any]], str | None]:
    params = {
        "sortColumns": "REPORT_DATE",
        "sortTypes": "-1",
        "pageSize": "20",
        "pageNumber": "1",
        "reportName": "RPT_PUBLIC_BS_APPOIN",
        "columns": "ALL",
        "quoteColumns": "",
        "source": "WEB",
        "client": "WEB",
        "filter": f'(SECURITY_CODE="{code}")(REPORT_YEAR="2026")',
    }
    headers = {"User-Agent": "Mozilla/5.0", "Referer": "https://data.eastmoney.com/bbsj/yysj.html"}
    try:
        response = requests.get("https://datacenter-web.eastmoney.com/api/data/v1/get", params=params, headers=headers, timeout=(5, 15))
        response.raise_for_status()
        data = response.json().get("result") or {}
        rows = data.get("data") or []
        if not isinstance(rows, list):
            return [], "unexpected_result_shape"
        return rows, None
    except Exception as exc:
        return [], str(exc)


def report_rank(row: dict[str, Any]) -> int:
    label = disclosure_report_label(row)
    if "半年" in label:
        return 1
    if "一季" in label:
        return 2
    if "三季" in label:
        return 3
    if "年报" in label:
        return 4
    return 9


def next_validation_focus_for_ticker(ticker: dict[str, Any]) -> str:
    code = ticker["code"]
    theme = ticker["theme"]
    if theme == "钨":
        return "核验钨价、库存、二季度利润、现金流和高纯钨材客户/订单。"
    if theme == "氟化工":
        return "核验制冷剂价差、HFC配额兑现、电子材料客户/订单/价差。"
    if code == "688146":
        return "核验WF6/NF3订单金额、合同均价、收入确认、客户份额和单品毛利。"
    if code == "688549":
        return "核验WF6利用率、长单/大额订单、收入确认、现金消耗和收入占比。"
    if code in {"600378", "688268"}:
        return "核验WF6收入占比、客户订单、价格条款、平台毛利和分部利润。"
    return "核验电子特气客户认证、订单、合同均价、收入占比、确认和单品毛利。"


def earnings_disclosure_calendar_complete(packet: dict[str, Any]) -> bool:
    rows = packet.get("rows", [])
    codes = {r.get("ticker") for r in rows}
    required_keys = {
        "ticker",
        "company",
        "next_report_type",
        "report_period",
        "appointment_date",
        "disclosure_status",
        "next_quarter_validation",
        "evidence_boundary",
    }
    if packet.get("schema") != "astock.earnings_disclosure_calendar.v1":
        return False
    if packet.get("covered_tickers") != len(TICKERS) or {t["code"] for t in TICKERS} - codes:
        return False
    if any(any(r.get(k) in (None, "", []) for k in required_keys) for r in rows):
        return False
    return any(r.get("ticker") == "688146" and r.get("appointment_date") == "2026-07-18" and "半年报" in r.get("next_report_type", "") for r in rows)


def normalize_earnings_disclosure_calendar_packet(packet: dict[str, Any]) -> dict[str, Any]:
    ticker_by_code = {ticker["code"]: ticker for ticker in TICKERS}
    for row in packet.get("rows", []):
        ticker = ticker_by_code.get(str(row.get("ticker", "")))
        if ticker:
            row["next_quarter_validation"] = next_validation_focus_for_ticker(ticker)
    return packet


def fetch_earnings_disclosure_calendar_snapshot(rows: list[dict[str, Any]]) -> dict[str, Any]:
    cache_path = CASE / "data/earnings_disclosure_calendar.json"
    if os.getenv("ASTOCK_REFRESH_DISCLOSURE_CALENDAR") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            cached = normalize_earnings_disclosure_calendar_packet(cached)
            if earnings_disclosure_calendar_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass
    row_by_code = {r["code"]: r for r in rows}
    output_rows: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        raw_rows, error = fetch_eastmoney_disclosure_calendar_rows(code)
        if error:
            errors.append({"ticker": code, "company": ticker["name"], "source": "eastmoney.RPT_PUBLIC_BS_APPOIN", "error": error})
        ordered = sorted(raw_rows, key=lambda x: (disclosure_status_cn(x) == "已披露", report_rank(x), str(x.get("REPORT_DATE") or "")))
        next_row = next((x for x in ordered if disclosure_status_cn(x) == "待披露"), ordered[0] if ordered else {})
        last_row = next((x for x in sorted(raw_rows, key=lambda x: str(x.get("REPORT_DATE") or ""), reverse=True) if disclosure_status_cn(x) == "已披露"), {})
        next_report_type = disclosure_report_label(next_row) if next_row else "未抓取"
        report_period = str(next_row.get("REPORT_DATE") or "")[:10] if next_row else ""
        appointment_date = str(next_row.get("APPOINT_PUBLISH_DATE") or "")[:10] if next_row else ""
        actual_date = str(next_row.get("ACTUAL_PUBLISH_DATE") or "")[:10] if next_row.get("ACTUAL_PUBLISH_DATE") else ""
        row_for_model = row_by_code.get(code, {})
        output_rows.append(
            {
                "ticker": code,
                "company": ticker["name"],
                "theme": ticker["theme"],
                "next_report_type": next_report_type,
                "report_period": report_period,
                "appointment_date": appointment_date,
                "actual_publish_date": actual_date or "未披露",
                "disclosure_status": disclosure_status_cn(next_row),
                "days_to_appointment": days_to_date(appointment_date),
                "last_published_report_type": disclosure_report_label(last_row) if last_row else "未抓取",
                "last_actual_publish_date": str(last_row.get("ACTUAL_PUBLISH_DATE") or last_row.get("APPOINT_PUBLISH_DATE") or "")[:10] if last_row else "",
                "next_quarter_validation": next_validation_focus_for_ticker(ticker),
                "valuation_link": row_for_model.get("next_quarter_threshold", "下一季财报刷新收入、利润、毛利和订单验证门槛。"),
                "evidence_use": "定义财报验证窗口、模型刷新时间和公告追踪优先级。",
                "evidence_boundary": "业绩披露日历只说明何时验证财报和公告，不证明订单、合同平均售价、收入确认比例、客户份额、单品收入或单品毛利。",
                "source_name": "东方财富业绩预约披露日历",
                "source_url": "https://data.eastmoney.com/bbsj/yysj.html",
            }
        )
    return {
        "schema": "astock.earnings_disclosure_calendar.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "source": "eastmoney.datacenter.RPT_PUBLIC_BS_APPOIN",
        "source_url": "https://data.eastmoney.com/bbsj/yysj.html",
        "covered_tickers": len({r["ticker"] for r in output_rows}),
        "next_report_rows": len(output_rows),
        "unpublished_next_report_rows": sum(1 for r in output_rows if r["disclosure_status"] == "待披露"),
        "upcoming_with_appointment_rows": sum(1 for r in output_rows if r.get("appointment_date")),
        "use_boundary": "业绩披露日历用于把下一季验证门槛绑定到预约披露窗口；不得替代实际财报结果、订单、合同平均售价、收入确认比例、客户份额、单品收入或单品毛利。",
        "rows": output_rows,
        "errors": errors,
    }


def earnings_disclosure_calendar_pdf_rows(limit: int | None = None) -> list[list[Any]]:
    rows = EARNINGS_DISCLOSURE_CALENDAR_SNAPSHOT.get("rows", [])
    ordered = sorted(rows, key=lambda r: (r.get("appointment_date") or "9999-12-31", r.get("ticker", "")))
