def fetch_public_price_proxy_snapshot() -> dict[str, Any]:
    cache_path = CASE / "data/public_price_proxy_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_PRICE_PROXY") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if cached.get("schema") == "astock.public_price_proxy.v1" and len(cached.get("rows", [])) >= 8:
                cached["cache_used"] = True
                return cached
        except Exception:
            pass
    rows = static_public_price_proxy_rows()
    errors: list[dict[str, Any]] = []
    try:
        import akshare as ak  # noqa: PLC0415

        df = ak.macro_china_commodity_price_index()
        latest = df.tail(1).to_dict("records")[0]
        rows.append(
            {
                "theme": "宏观价格背景",
                "proxy_item": "中国大宗商品价格指数",
                "proxy_type": "AkShare宏观商品价格指数",
                "as_of": str(latest.get("日期")),
                "value": str(latest.get("最新值")),
                "trend": f"近3月{fmt_points(latest.get('近3月涨跌幅'))}；近1年{fmt_points(latest.get('近1年涨跌幅'))}",
                "source_ids": ["AK_macro_china_commodity_price_index"],
                "source_path": "akshare.macro_china_commodity_price_index",
                "valuation_use": "只作为全市场商品价格背景，不替代钨、制冷剂或WF6单品价格",
                "remaining_gap": "不能用于公司ASP、单品毛利或订单收入确认",
            }
        )
    except Exception as exc:
        errors.append({"source": "akshare.macro_china_commodity_price_index", "error": str(exc)})
    return {
        "schema": "astock.public_price_proxy.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "source": "archived_public_sources_plus_akshare_macro_index",
        "rows": rows,
        "errors": errors,
        "cache_used": False,
        "boundary": "行业价格、出口均价、报价通知、成本占比和宏观指数只能作为价格代理；不能替代公司合同ASP、产品毛利、订单金额或收入确认比例。",
    }


def public_price_proxy_rows() -> list[dict[str, Any]]:
    return PUBLIC_PRICE_PROXY_SNAPSHOT.get("rows", [])


def public_price_proxy_md() -> str:
    rows = public_price_proxy_rows()
    errors = PUBLIC_PRICE_PROXY_SNAPSHOT.get("errors", [])
    err_text = "无" if not errors else "；".join(f"{e.get('source')}:{e.get('error')}" for e in errors[:4])
    return "# 公开价格代理边界包\n\n门禁状态：有条件通过。本包补齐钨价、WF6出口均价、海外报价、成本占比、制冷剂配额和宏观商品指数等公开价格代理。它们可以解释主题热度、成本压力和市场锚，但不能替代公司合同ASP、产品毛利、订单金额或收入确认比例。\n\n" + md_table(
        ["主题", "代理项", "口径", "日期", "数值", "趋势", "估值用途", "仍缺字段"],
        [[r["theme"], r["proxy_item"], r["proxy_type"], r["as_of"], r["value"], r["trend"], r["valuation_use"], r["remaining_gap"]] for r in rows],
    ) + f"\n\n- 覆盖代理：{len(rows)}\n- 抓取错误：{err_text}\n- 边界：行业价格不等于公司合同ASP；公开价格代理不能直接进入增长EPS。\n"


def public_price_proxy_pdf_rows(limit: int = 7) -> list[list[Any]]:
    preferred = [r for r in public_price_proxy_rows() if r.get("theme") in {"钨", "电子特气", "氟化工"}]
    return [
        [
            r["theme"],
            r["proxy_item"],
            r["value"],
            r["trend"],
            r["valuation_use"],
            r["remaining_gap"],
        ]
        for r in preferred[:limit]
    ]


def eastmoney_symbol(code: str) -> str:
    return ("SH" if code.startswith(("6", "9")) else "SZ") + code


def safe_float_value(value: Any) -> float | None:
    value = clean_cell(value)
    if value is None:
        return None
    try:
        f = float(value)
    except Exception:
        return None
    if math.isnan(f) or math.isinf(f):
        return None
    return f


def fetch_business_segment_snapshot() -> dict[str, Any]:
    cache_path = CASE / "data/business_segment_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_BUSINESS_SEGMENT") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if cached.get("covered_tickers", 0) >= 18 and len(cached.get("rows", [])) >= 50:
                cached["cache_used"] = True
                return cached
        except Exception:
            pass
    sys.path.insert(0, str(ROOT / "src" / "python"))
    try:
        import akshare as ak  # noqa: PLC0415
    except Exception as exc:
        return {
            "schema": "astock.business_segment_snapshot.v1",
            "generated_at": now_cst(),
            "source": "akshare.stock_zygc_em",
            "rows": [],
            "errors": [{"stage": "import_akshare", "error": str(exc)}],
        }

    rows: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        try:
            df = ak.stock_zygc_em(symbol=eastmoney_symbol(code))
        except Exception as exc:
            errors.append({"ticker": code, "company": ticker["name"], "error": str(exc)})
            continue
        if df is None or df.empty:
            errors.append({"ticker": code, "company": ticker["name"], "error": "empty"})
            continue
        records = df.to_dict("records")
        product_records = [r for r in records if str(r.get("分类类型", "")).strip() == "按产品分类"]
        if not product_records:
            errors.append({"ticker": code, "company": ticker["name"], "error": "no_product_rows"})
            continue
        latest_date = max(str(r.get("报告日期", "")) for r in product_records)
        latest_rows = [r for r in product_records if str(r.get("报告日期", "")) == latest_date]
        for raw in latest_rows:
            rows.append(
                {
                    "ticker": code,
                    "company": ticker["name"],
                    "theme": ticker["theme"],
                    "report_date": str(clean_cell(raw.get("报告日期")) or latest_date),
                    "classification": "product",
                    "segment": str(clean_cell(raw.get("主营构成")) or "未披露"),
                    "revenue": safe_float_value(raw.get("主营收入")),
                    "revenue_share": safe_float_value(raw.get("收入比例")),
                    "cost": safe_float_value(raw.get("主营成本")),
                    "cost_share": safe_float_value(raw.get("成本比例")),
                    "gross_profit": safe_float_value(raw.get("主营利润")),
                    "gross_profit_share": safe_float_value(raw.get("利润比例")),
                    "gross_margin": safe_float_value(raw.get("毛利率")),
                    "source": "eastmoney_business_analysis",
                    "data_quality": "public_segment_mix",
                }
            )
    return {
        "schema": "astock.business_segment_snapshot.v1",
        "generated_at": now_cst(),
        "source": "akshare.stock_zygc_em",
        "covered_tickers": len({r["ticker"] for r in rows}),
        "rows": rows,
        "errors": errors,
    }


def business_segment_rows_by_ticker() -> dict[str, list[dict[str, Any]]]:
    by_code: dict[str, list[dict[str, Any]]] = {}
    for row in BUSINESS_SEGMENT_SNAPSHOT.get("rows", []):
        by_code.setdefault(str(row.get("ticker", "")), []).append(row)
    for code in by_code:
        by_code[code].sort(key=lambda x: float(x.get("revenue_share") or 0.0), reverse=True)
    return by_code


def business_segment_top_rows(code: str, limit: int = 3) -> list[dict[str, Any]]:
    return business_segment_rows_by_ticker().get(code, [])[:limit]


def business_segment_mix_text(code: str, limit: int = 3) -> str:
    parts = []
    for row in business_segment_top_rows(code, limit):
        parts.append(f"{row['segment']} {fmt_pct(row.get('revenue_share'))}/毛利{fmt_pct(row.get('gross_margin'))}")
    return "；".join(parts) if parts else "未获取主营构成"


def business_segment_primary_text(code: str) -> str:
    top = business_segment_top_rows(code, 1)
    if not top:
        return "未获取"
    row = top[0]
    return f"{row['segment']}，收入占比{fmt_pct(row.get('revenue_share'))}，毛利率{fmt_pct(row.get('gross_margin'))}"


def business_segment_implication(ticker: dict[str, Any]) -> str:
    code = ticker["code"]
    top_text = business_segment_mix_text(code, 2)
    if ticker["theme"] == "钨":
        return f"{top_text}；已补产品结构，但半导体高纯钨材仍未单列"
    if ticker["theme"] == "氟化工":
        return f"{top_text}；已补产品结构，客户/订单仍需公告验证"
    if code == "600378":
        return f"{top_text}；WF6单品0.13%证据继续约束估值"
    if code == "688146":
        return f"{top_text}；电子特气收入占比高，但WF6/NF3单品未拆"
    if code == "688549":
        return f"{top_text}；电子特气及前驱体已单列，WF6单品未拆"
    if code == "688268":
        return f"{top_text}；特气平台清晰，但纯化WF6占比仍未披露"
    return f"{top_text}；具体电子特气单品和客户订单仍未披露"


def business_segment_snapshot_md() -> str:
    by_code = business_segment_rows_by_ticker()
    table_rows = []
    for ticker in TICKERS:
        code = ticker["code"]
        top = business_segment_top_rows(code, 1)
        report_date = top[0]["report_date"] if top else "未获取"
        table_rows.append(
            [
                code,
                ticker["name"],
                report_date,
                business_segment_mix_text(code, 3),
                business_segment_primary_text(code),
                business_segment_implication(ticker),
            ]
        )
    errors = BUSINESS_SEGMENT_SNAPSHOT.get("errors", [])
    err_text = "无" if not errors else "；".join(f"{e.get('ticker', e.get('stage'))}:{e.get('error')}" for e in errors[:8])
    return "# 主营构成与产品毛利率快照\n\n门禁状态：通过。该数据来自东方财富主营构成公开接口，补齐每只覆盖标的最新年度产品收入占比、产品毛利率和主导利润池。它能补充产品结构，但不能替代WF6单品、具名客户、订单金额或合同价格。\n\n" + md_table(
        ["代码", "名称", "报告期", "前三产品/收入占比/毛利率", "第一产品", "投资含义"],
        table_rows,
    ) + f"\n\n- 原始产品行数：{len(BUSINESS_SEGMENT_SNAPSHOT.get('rows', []))}\n- 覆盖标的：{len(by_code)}\n- 抓取错误：{err_text}\n"


