def customer_qualification_evidence_packet() -> dict[str, Any]:
    rows = customer_qualification_evidence_rows()
    return {
        "schema": "astock.customer_qualification_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "rows": rows,
        "covered_tickers": len({r["ticker"] for r in rows}),
        "source": "sources/official-annual-reports-2025",
        "use_boundary": "客户认证/具名客户披露证明客户链可见度、认证门槛或供货阶段，不替代单品客户份额、订单金额、合同ASP、收入确认比例或单品毛利。",
    }


def customer_qualification_evidence_md() -> str:
    rows = CUSTOMER_QUALIFICATION_EVIDENCE_SNAPSHOT.get("rows", [])
    table_rows = [
        [
            r["ticker"],
            r["company"],
            r["evidence_layer"],
            r["named_customer_evidence"],
            r["certification_or_supply_evidence"],
            r["customer_share_or_scope"],
            r["valuation_use"],
            r["remaining_gap"],
        ]
        for r in rows
    ]
    return "# 客户认证/具名客户披露证据\n\n门禁状态：有条件通过。本包把年报中真正有信息量的客户、认证、批量供货和客户集中度披露单独成包，修正“只看到关键词、没有客户链证据”的问题。它能提高客户链置信度、排序调研优先级和风险折扣判断，但不替代单品客户份额、订单金额、合同ASP、收入确认比例或单品毛利。\n\n" + md_table(
        ["代码", "名称", "证据层", "具名客户/客户范围", "认证/供货阶段", "份额或范围", "估值用途", "仍缺字段"],
        table_rows,
    ) + f"\n\n- 覆盖标的：{CUSTOMER_QUALIFICATION_EVIDENCE_SNAPSHOT.get('covered_tickers', 0)}\n- 来源：`sources/official-annual-reports-2025/`\n- 使用边界：客户认证/具名客户披露不替代单品客户份额、订单金额、合同ASP、收入确认比例或单品毛利。\n"


def customer_qualification_rows_by_ticker() -> dict[str, dict[str, Any]]:
    return {str(r.get("ticker")): r for r in CUSTOMER_QUALIFICATION_EVIDENCE_SNAPSHOT.get("rows", [])}


def customer_qualification_summary_text(code: str) -> str:
    row = customer_qualification_rows_by_ticker().get(code)
    if not row:
        return "未形成单独客户认证证据包；仍需客户侧文件或公告验证。"
    return f"{reader_text(row.get('named_customer_evidence'))}；{reader_text(row.get('certification_or_supply_evidence'))}；边界：不替代单品客户份额、订单、ASP或毛利。"


