def production_sales_inventory_packet() -> dict[str, Any]:
    rows = production_sales_inventory_rows()
    return {
        "schema": "astock.production_sales_inventory_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "rows": rows,
        "covered_tickers": len({r["ticker"] for r in rows}),
        "covered_themes": sorted({ticker["theme"] for ticker in TICKERS if ticker["code"] in {r["ticker"] for r in rows}}),
        "use_boundary": "产销量、库存和产能利用率证明产能兑现、库存压力和大类业务景气；不得替代WF6/NF3/电子材料/高纯钨材单品收入、客户份额、订单金额、合同ASP、收入确认比例或单品毛利。",
    }


def production_sales_inventory_md() -> str:
    rows = production_sales_inventory_rows()
    return "# 产销量/库存/产能利用证据包\n\n门禁状态：有条件通过。本包从18份2025年年度报告中摘出公司披露的产量、销量、库存、产能利用率或客户侧库存服务证据，用于回答“产能是否有产销兑现和库存约束”。它能补强公司基本面分析和产能兑现监测，但不能把产能、销量或利用率直接折算为WF6/NF3/电子材料/高纯钨材的订单、合同ASP、收入确认比例或单品毛利。\n\n" + md_table(
        ["代码", "名称", "证据层", "产品/分部", "生产证据", "销售证据", "库存证据", "产能/利用率", "兑现信号", "来源", "估值用途", "证据边界", "仍缺字段"],
        [[r["ticker"], r["company"], r["evidence_layer"], r["product_or_segment"], r["production_evidence"], r["sales_evidence"], r["inventory_evidence"], r["capacity_or_utilization_evidence"], r["conversion_signal"], f"{r['source_path']}:{r['line_reference']}", r["valuation_use"], r["evidence_boundary"], r["remaining_gap"]] for r in rows],
    ) + f"\n\n- 覆盖标的：{PRODUCTION_SALES_INVENTORY_SNAPSHOT.get('covered_tickers', len(rows))}/18\n- 来源：`sources/official-annual-reports-2025/`\n- 使用边界：产销量/库存/产能利用只证明产能兑现和供需约束，不替代单品客户、订单、ASP、收入确认比例或单品毛利。\n"


def production_sales_inventory_rows_by_ticker() -> dict[str, dict[str, Any]]:
    return {str(r.get("ticker")): r for r in PRODUCTION_SALES_INVENTORY_SNAPSHOT.get("rows", [])}


def production_sales_inventory_summary_text(code: str) -> str:
    row = production_sales_inventory_rows_by_ticker().get(code)
    if not row:
        return "未形成产销量/库存/产能利用证据；需继续查年报表格或公告。"
    return f"{reader_text(row.get('report_summary'))}；边界：不替代单品客户、订单、ASP或毛利。"


