def cost_margin_pass_through_md() -> str:
    rows = COST_MARGIN_PASS_THROUGH_SNAPSHOT.get("rows", [])
    return "# 成本结构/毛利/价格传导证据包\n\n门禁状态：有条件通过。本包从18份2025年年度报告中摘出成本构成、平台/大类毛利率、价格传导或成本转嫁机制，用于修正“只有收入叙事、没有利润弹性门禁”的问题。它只能约束利润敏感性、风险折扣和估值信用等级，不能替代WF6/NF3/电子级HF/高纯钨材等单品毛利率、合同ASP、订单金额或客户份额。\n\n" + md_table(
        ["代码", "名称", "证据层", "产品/分部", "毛利/利润证据", "成本结构", "价格传导", "成本风险", "利润信号", "来源", "估值用途", "证据边界", "仍缺字段"],
        [
            [
                r["ticker"],
                r["company"],
                r["evidence_layer"],
                r["product_or_segment"],
                r["gross_margin_or_profit_evidence"],
                r["cost_structure_evidence"],
                r["price_pass_through_evidence"],
                r["raw_material_or_energy_risk"],
                r["margin_signal"],
                f"{r['source_path']}:{r['line_reference']}",
                r["valuation_use"],
                r["evidence_boundary"],
                r["remaining_gap"],
            ]
            for r in rows
        ],
    ) + f"\n\n- 覆盖标的：{COST_MARGIN_PASS_THROUGH_SNAPSHOT.get('covered_tickers', len(rows))}/18\n- 来源：`sources/official-annual-reports-2025/`\n- 使用边界：该包不关闭单品毛利率、合同ASP、订单金额或客户份额缺口；只能提高利润弹性讨论的可核验性。\n"


def cost_margin_pass_through_rows_by_ticker() -> dict[str, dict[str, Any]]:
    return {str(r.get("ticker")): r for r in COST_MARGIN_PASS_THROUGH_SNAPSHOT.get("rows", [])}


def cost_margin_pass_through_summary_text(code: str) -> str:
    row = cost_margin_pass_through_rows_by_ticker().get(code)
    if not row:
        return "未形成成本毛利/价格传导证据；需继续查年报成本分析或调研纪要。"
    return f"{reader_text(row.get('report_summary'))}；边界：不替代单品毛利、合同ASP或订单。"


