    rows = competitive_position_rows()
    return {
        "schema": "astock.competitive_position_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "rows": rows,
        "covered_tickers": len({r["ticker"] for r in rows}),
        "source": "sources/official-annual-reports-2025",
        "use_boundary": "竞争格局/行业地位证据不替代单品收入、客户份额、订单金额、合同ASP或单品毛利；只能提高关系置信度、市场锚权重、风险折扣和调研优先级。",
    }


