def annual_theme_hits(text: str, keywords: list[str]) -> list[dict[str, Any]]:
    hits = []
    for keyword in keywords:
        count = len(re.findall(re.escape(keyword), text, flags=re.IGNORECASE))
        if count:
            hits.append({"term": keyword, "count": count})
    hits.sort(key=lambda x: (-int(x["count"]), str(x["term"])))
    return hits


def annual_terms_text(hits: list[dict[str, Any]], limit: int = 5) -> str:
    if not hits:
        return "未找到"
    return "、".join(f"{h['term']}({h['count']})" for h in hits[:limit])


def theme_evidence_status(row: dict[str, Any]) -> str:
    product = bool(row.get("product_terms"))
    customer = bool(row.get("customer_platform_terms"))
    cert = bool(row.get("certification_terms"))
    capacity = bool(row.get("capacity_project_terms"))
    order_proxy = bool(row.get("order_proxy_terms"))
    if product and customer and (cert or capacity or order_proxy):
        return "年报具备产品+客户/平台+认证/产能代理"
    if product and (cert or capacity):
        return "年报具备产品+认证/产能代理"
    if product:
        return "年报仅具备产品暴露"
    return "年报未找到主题产品证据"


def theme_evidence_gate(ticker: dict[str, Any], status: str) -> str:
    if ticker["theme"] == "电子特气":
        if "产品+客户/平台+认证/产能代理" in status:
            return "期权信用；单品订单/ASP/毛利前不给盈利信用"
        if "产品" in status:
            return "观察信用；需补客户、订单、ASP和毛利"
        return "观察名单；缺主题产品证据"
    if ticker["theme"] == "氟化工":
        if "产品" in status:
            return "基准业务信用；电子材料第二曲线需单独验证"
        return "周期/资源信用；电子材料信用不足"
    if "产品" in status:
        return "资源/制造信用；半导体高纯钨材需单独验证"
    return "资源信用；半导体外延不足"


def theme_evidence_gap(ticker: dict[str, Any], row: dict[str, Any]) -> str:
    if ticker["theme"] == "电子特气":
        gaps = ["单品收入", "单品毛利", "合同ASP", "订单金额/期限"]
        if not row.get("customer_platform_terms"):
            gaps.append("客户/平台")
        return "；".join(gaps)
    if ticker["theme"] == "氟化工":
        return "电子材料收入占比；电子材料客户/订单；合同ASP；单品毛利"
    return "半导体高纯钨材收入；客户/订单；合同ASP；单品毛利"


def annual_theme_evidence_complete(packet: dict[str, Any]) -> bool:
    rows = packet.get("rows", [])
    required = {t["code"] for t in TICKERS}
    covered = {r.get("ticker") for r in rows}
    if not required <= covered:
        return False
    for row in rows:
        for key in ["annual_report_text_path", "theme_evidence_status", "valuation_gate", "evidence_gap"]:
            if row.get(key) in (None, ""):
                return False
        if not row.get("product_terms"):
            return False
    return True


def fetch_annual_report_theme_evidence_snapshot() -> dict[str, Any]:
    cache_path = CASE / "data/annual_report_theme_evidence_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_ANNUAL_THEME_EVIDENCE") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if annual_theme_evidence_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass

    rows: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        _, text_path = annual_report_paths(ticker)
        try:
            if not text_path.exists() or text_path.stat().st_size == 0:
                raise FileNotFoundError(str(text_path.relative_to(CASE)))
            text = text_path.read_text(encoding="utf-8", errors="ignore")
            row: dict[str, Any] = {
                "ticker": code,
                "company": ticker["name"],
                "theme": ticker["theme"],
                "annual_report_text_path": str(text_path.relative_to(CASE)),
                "product_terms": annual_theme_hits(text, THEMATIC_EVIDENCE_KEYWORDS["product"]),
                "customer_platform_terms": annual_theme_hits(text, THEMATIC_EVIDENCE_KEYWORDS["customer_platform"]),
                "certification_terms": annual_theme_hits(text, THEMATIC_EVIDENCE_KEYWORDS["certification"]),
                "capacity_project_terms": annual_theme_hits(text, THEMATIC_EVIDENCE_KEYWORDS["capacity_project"]),
                "order_proxy_terms": annual_theme_hits(text, THEMATIC_EVIDENCE_KEYWORDS["order_proxy"]),
                "source": "cninfo_annual_report_2025_keyword_scan",
                "data_quality": "annual_report_keyword_evidence",
            }
            row["theme_evidence_status"] = theme_evidence_status(row)
            row["valuation_gate"] = theme_evidence_gate(ticker, row["theme_evidence_status"])
            row["evidence_gap"] = theme_evidence_gap(ticker, row)
            rows.append(row)
        except Exception as exc:
            errors.append({"ticker": code, "company": ticker["name"], "error": str(exc)})
            rows.append(
                {
                    "ticker": code,
                    "company": ticker["name"],
                    "theme": ticker["theme"],
                    "annual_report_text_path": "",
                    "product_terms": [],
                    "customer_platform_terms": [],
                    "certification_terms": [],
                    "capacity_project_terms": [],
                    "order_proxy_terms": [],
                    "theme_evidence_status": "年报未解析",
                    "valuation_gate": "观察名单；缺年报文本",
                    "evidence_gap": "年报文本缺失",
                    "source": "cninfo_annual_report_2025_keyword_scan",
                    "data_quality": "annual_report_keyword_scan_failed",
                }
            )
    return {
        "schema": "astock.annual_report_theme_evidence.v1",
        "generated_at": now_cst(),
        "source": "cninfo_annual_report_2025_keyword_scan",
        "covered_tickers": len({r["ticker"] for r in rows if r.get("product_terms")}),
        "rows": rows,
        "errors": errors,
    }


