def compact_excerpt(text: str, max_len: int = 86) -> str:
    cleaned = re.sub(r"\s+", "", text).replace("|", "/")
    cleaned = cleaned.replace("□适用√不适用", "").replace("√适用□不适用", "")
    cleaned = cleaned.replace("�", "").replace("", "").replace("□", "").replace("√", "")
    if len(cleaned) <= max_len:
        return cleaned
    return cleaned[: max_len - 1] + "…"


def annual_report_excerpt_for_keywords(text: str, keywords: list[str]) -> dict[str, Any]:
    for keyword in keywords:
        match = re.search(re.escape(keyword), text, flags=re.IGNORECASE)
        if not match:
            continue
        start = max(0, match.start() - 42)
        end = min(len(text), match.end() + 98)
        return {
            "term": keyword,
            "page": text.count("\f", 0, match.start()) + 1,
            "excerpt": compact_excerpt(text[start:end]),
        }
    return {"term": "", "page": None, "excerpt": "未找到"}


def annual_report_snippet_row_complete(row: dict[str, Any]) -> bool:
    if row.get("annual_report_text_path") in (None, ""):
        return False
    if row.get("product_excerpt", {}).get("excerpt") in (None, "", "未找到"):
        return False
    if row.get("snippet_count", 0) < 1:
        return False
    return True


def annual_report_snippet_complete(packet: dict[str, Any]) -> bool:
    rows = packet.get("rows", [])
    required = {t["code"] for t in TICKERS}
    covered = {r.get("ticker") for r in rows}
    return required <= covered and all(annual_report_snippet_row_complete(r) for r in rows)


def annual_snippet_gate(ticker: dict[str, Any], snippets: dict[str, dict[str, Any]]) -> str:
    product = snippets["product"]["excerpt"] != "未找到"
    customer = snippets["customer_platform"]["excerpt"] != "未找到"
    cert = snippets["certification"]["excerpt"] != "未找到"
    capacity = snippets["capacity_project"]["excerpt"] != "未找到"
    order = snippets["order_proxy"]["excerpt"] != "未找到"
    if ticker["theme"] == "电子特气":
        if product and customer and (cert or capacity or order):
            return "可提升电子特气关系优先级；仍不得替代订单、ASP或毛利"
        if product:
            return "仅支持产品暴露；客户/订单/价格仍待补证"
        return "年报短摘不足；维持观察"
    if ticker["theme"] == "氟化工":
        if product:
            return "支持氟化工/电子材料披露可见度；第二曲线仍需订单和收入拆分"
        return "仅维持制冷剂/资源主线"
    if product:
        return "支持钨产品披露可见度；半导体高纯钨材仍需客户和订单"
    return "仅维持资源/制造基准信用"


def fetch_annual_report_evidence_snippet_snapshot() -> dict[str, Any]:
    cache_path = CASE / "data/annual_report_evidence_snippet_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_ANNUAL_SNIPPETS") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if annual_report_snippet_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass

    rows: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    categories = {
        "product": THEMATIC_EVIDENCE_KEYWORDS["product"],
        "customer_platform": THEMATIC_EVIDENCE_KEYWORDS["customer_platform"],
        "certification": THEMATIC_EVIDENCE_KEYWORDS["certification"],
        "capacity_project": ["产能", "扩产", "投产", "生产线", "建设", "项目"],
        "order_proxy": ["在手订单", "长协", "长期协议", "框架协议", "订单", "合同", "洽谈"],
    }
    for ticker in TICKERS:
        code = ticker["code"]
        _, text_path = annual_report_paths(ticker)
        try:
            if not text_path.exists() or text_path.stat().st_size == 0:
                raise FileNotFoundError(str(text_path.relative_to(CASE)))
            text = text_path.read_text(encoding="utf-8", errors="ignore")
            snippets = {name: annual_report_excerpt_for_keywords(text, keywords) for name, keywords in categories.items()}
            snippet_count = sum(1 for value in snippets.values() if value.get("excerpt") != "未找到")
            rows.append(
                {
                    "ticker": code,
                    "company": ticker["name"],
                    "theme": ticker["theme"],
                    "annual_report_text_path": str(text_path.relative_to(CASE)),
                    "snippet_count": snippet_count,
                    "product_excerpt": snippets["product"],
                    "customer_platform_excerpt": snippets["customer_platform"],
                    "certification_excerpt": snippets["certification"],
                    "capacity_project_excerpt": snippets["capacity_project"],
                    "order_proxy_excerpt": snippets["order_proxy"],
                    "valuation_gate": annual_snippet_gate(ticker, snippets),
                    "evidence_boundary": "年报短摘证明披露可见度，不证明单品订单、合同ASP、收入确认比例、客户份额或单品毛利。",
                    "source": "cninfo_annual_report_2025_short_excerpt",
                    "data_quality": "annual_report_primary_excerpt",
                }
            )
        except Exception as exc:
            errors.append({"ticker": code, "company": ticker["name"], "error": str(exc)})
            rows.append(
                {
                    "ticker": code,
                    "company": ticker["name"],
                    "theme": ticker["theme"],
                    "annual_report_text_path": "",
                    "snippet_count": 0,
                    "product_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "customer_platform_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "certification_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "capacity_project_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "order_proxy_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "valuation_gate": "年报短摘缺失；不得用于关系升级",
                    "evidence_boundary": "年报文本缺失。",
                    "source": "cninfo_annual_report_2025_short_excerpt",
                    "data_quality": "annual_report_excerpt_failed",
                }
            )
    return {
        "schema": "astock.annual_report_evidence_snippet.v1",
        "generated_at": now_cst(),
        "source": "cninfo_annual_report_2025_short_excerpt",
        "covered_tickers": len({r["ticker"] for r in rows if annual_report_snippet_row_complete(r)}),
        "rows": rows,
        "errors": errors,
        "use_boundary": "短摘只用于证据可读性和关系优先级，不进入增长EPS或基本面目标价。",
    }


