def annual_excerpt_text(value: dict[str, Any], limit: int = 72) -> str:
    excerpt = value.get("excerpt") if isinstance(value, dict) else None
    if not excerpt or excerpt == "未找到":
        return "未找到"
    term = value.get("term") or "命中"
    page = value.get("page")
    prefix = f"{term}@p{page}" if page else str(term)
    return f"{prefix}：{compact_excerpt(excerpt, limit)}"


def annual_snippet_summary_text(code: str) -> str:
    row = annual_report_snippet_rows_by_ticker().get(code)
    if not row:
        return "未获取"
    return (
        f"产品短摘：{annual_excerpt_text(row.get('product_excerpt', {}), 54)}；"
        f"客户/平台短摘：{annual_excerpt_text(row.get('customer_platform_excerpt', {}), 54)}；"
        f"门禁：{row.get('valuation_gate', '未获取')}"
    )


def annual_snippet_combo_text(row: dict[str, Any], limit: int = 42, max_items: int = 3) -> str:
    cert = annual_excerpt_text(row.get("certification_excerpt", {}), limit)
    capacity = annual_excerpt_text(row.get("capacity_project_excerpt", {}), limit)
    order = annual_excerpt_text(row.get("order_proxy_excerpt", {}), limit)
    items = [x for x in [cert, capacity, order] if x != "未找到"]
    return "；".join(items[:max_items]) or "未找到"


