def annual_report_anchor_offset(text: str, anchors: list[str]) -> int:
    for anchor in anchors:
        matches = list(re.finditer(re.escape(anchor), text, flags=re.IGNORECASE))
        for match in matches:
            window = text[max(0, match.start() - 80) : min(len(text), match.end() + 120)]
            if re.search(r"\.{8,}|目录|CONTENTS", window, flags=re.IGNORECASE):
                continue
            return match.start()
    return 0


def annual_report_excerpt_score(excerpt: str, keyword: str, keyword_rank: int) -> float:
    cleaned = re.sub(r"\s+", "", excerpt)
    if not cleaned:
        return -999.0
    digit_ratio = sum(1 for char in cleaned if char.isdigit()) / max(len(cleaned), 1)
    score = max(0, 8 - keyword_rank) * 0.35
    for marker in ["变动原因说明", "主要原因", "主要原因为", "主要系", "主要是", "由于", "导致", "受", "带动", "提升", "下降", "增长", "改善", "承压", "风险", "应对", "影响", "需求", "价格", "成本", "存货", "应收", "订单", "客户", "市场"]:
        if marker in cleaned:
            score += 1.6
    if any(marker in cleaned for marker in ["变动原因说明", "主要原因为", "主要原因系", "主要系", "主要是"]):
        score += 5.0
    if "风险" in cleaned and any(marker in cleaned for marker in ["应对", "可能面对", "面临", "防范", "控制"]):
        score += 5.0
    if digit_ratio > 0.32:
        score -= 12.0
    elif digit_ratio > 0.22:
        score -= 5.0
    if re.search(r"(?:\d[\d,.%]{3,}){3,}", cleaned):
        score -= 9.0
    for marker in ["营业收入营业成本毛利率", "比上年营业成本比上年毛利率", "是否存在半数以上董事", "合并利润表", "资产负债表", "现金流量表", "单位：元"]:
        if marker in cleaned:
            score -= 8.0
    if cleaned.count("。") + cleaned.count("；") == 0 and digit_ratio > 0.12:
        score -= 3.0
    return score


def annual_report_excerpt_for_keywords_scoped(text: str, keywords: list[str], anchors: list[str]) -> dict[str, Any]:
    start_offset = annual_report_anchor_offset(text, anchors)
    scoped = text[start_offset:]
    best: dict[str, Any] | None = None
    best_score = -999.0
    for keyword_rank, keyword in enumerate(keywords):
        for match in re.finditer(re.escape(keyword), scoped, flags=re.IGNORECASE):
            absolute_start = start_offset + match.start()
            absolute_end = start_offset + match.end()
            start = max(0, absolute_start - 72)
            end = min(len(text), absolute_end + 176)
            raw_excerpt = text[start:end]
            score = annual_report_excerpt_score(raw_excerpt, keyword, keyword_rank)
            if score <= best_score:
                continue
            best_score = score
            best = {
                "term": keyword,
                "page": text.count("\f", 0, absolute_start) + 1,
                "excerpt": compact_excerpt(raw_excerpt, 128),
                "display_score": round(score, 2),
            }
    return best or {"term": "", "page": None, "excerpt": "未找到", "display_score": None}


def annual_report_mdna_row_complete(row: dict[str, Any]) -> bool:
    if row.get("annual_report_text_path") in (None, ""):
        return False
    return int(row.get("snippet_count") or 0) >= 3 and row.get("performance_excerpt", {}).get("excerpt") not in (None, "", "未找到")


def annual_report_mdna_complete(packet: dict[str, Any]) -> bool:
    rows = packet.get("rows", [])
    required = {t["code"] for t in TICKERS}
    covered = {r.get("ticker") for r in rows}
    return required <= covered and all(annual_report_mdna_row_complete(r) for r in rows)


def annual_report_mdna_gate(row: dict[str, Any]) -> str:
    risk_found = row.get("risk_excerpt", {}).get("excerpt") != "未找到"
    cash_found = row.get("cash_working_capital_excerpt", {}).get("excerpt") != "未找到"
    margin_found = row.get("margin_cost_excerpt", {}).get("excerpt") != "未找到"
    if risk_found and cash_found and margin_found:
        return "可用于公司整体业绩归因、现金流和风险解释；不进入单品EPS"
    if margin_found or cash_found:
        return "可辅助解释整体业绩；风险或现金流字段仍需人工核读"
    return "仅作年报语境；不得替代财务模型和单品证据"


def fetch_annual_report_mdna_snapshot() -> dict[str, Any]:
    cache_path = CASE / "data/annual_report_mdna_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_ANNUAL_MDNA") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if cached.get("schema") == "astock.annual_report_mdna.v3" and annual_report_mdna_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass

    rows: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        _, text_path = annual_report_paths(ticker)
        try:
            if not text_path.exists() or text_path.stat().st_size == 0:
                raise FileNotFoundError(str(text_path.relative_to(CASE)))
            text = text_path.read_text(encoding="utf-8", errors="ignore")
            excerpts = {
                name: annual_report_excerpt_for_keywords_scoped(text, spec["keywords"], spec["anchors"])
                for name, spec in MDNA_EVIDENCE_CATEGORIES.items()
            }
            snippet_count = sum(1 for value in excerpts.values() if value.get("excerpt") != "未找到")
            row = {
                "ticker": code,
                "company": ticker["name"],
                "theme": ticker["theme"],
                "annual_report_text_path": str(text_path.relative_to(CASE)),
                "snippet_count": snippet_count,
                "performance_excerpt": excerpts["performance"],
                "margin_cost_excerpt": excerpts["margin_cost"],
                "cash_working_capital_excerpt": excerpts["cash_working_capital"],
                "risk_excerpt": excerpts["risk"],
                "valuation_gate": "",
                "evidence_boundary": "管理层讨论摘录用于解释公司整体业绩、毛利/成本、现金流和风险，不证明单品收入、订单金额、合同ASP、客户份额或单品毛利。",
                "source": "cninfo_annual_report_2025_mdna_excerpt",
                "data_quality": "annual_report_primary_mdna_excerpt",
            }
            row["valuation_gate"] = annual_report_mdna_gate(row)
            rows.append(row)
        except Exception as exc:
            errors.append({"ticker": code, "company": ticker["name"], "error": str(exc)})
            rows.append(
                {
                    "ticker": code,
                    "company": ticker["name"],
                    "theme": ticker["theme"],
                    "annual_report_text_path": "",
                    "snippet_count": 0,
                    "performance_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "margin_cost_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "cash_working_capital_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "risk_excerpt": {"term": "", "page": None, "excerpt": "未找到"},
                    "valuation_gate": "年报管理层讨论摘录缺失；不得用于业绩归因",
                    "evidence_boundary": "年报文本缺失。",
                    "source": "cninfo_annual_report_2025_mdna_excerpt",
                    "data_quality": "annual_report_mdna_excerpt_failed",
                }
            )
    return {
        "schema": "astock.annual_report_mdna.v3",
        "generated_at": now_cst(),
        "source": "cninfo_annual_report_2025_mdna_excerpt",
        "covered_tickers": len({r["ticker"] for r in rows if annual_report_mdna_row_complete(r)}),
        "rows": rows,
        "errors": errors,
        "use_boundary": "管理层讨论只解释公司整体业绩归因、风险和现金流，不进入单品订单、ASP或增长EPS。",
    }


def annual_report_mdna_rows_by_ticker() -> dict[str, dict[str, Any]]:
    return {str(row.get("ticker")): row for row in ANNUAL_REPORT_MDNA_SNAPSHOT.get("rows", [])}


def annual_mdna_has(text: str, terms: list[str]) -> bool:
    return any(term in text for term in terms)


def annual_mdna_fallback_signal(value: dict[str, Any], limit: int = 26) -> str:
    excerpt = value.get("excerpt") if isinstance(value, dict) else None
    if not excerpt or excerpt == "未找到":
        return "未找到"
    cleaned = compact_excerpt(excerpt, 90)
    cleaned = re.sub(r"\d[\d,.%]{6,}", "", cleaned)
    for marker in ["主要原因", "主要系", "主要是", "风险", "应对措施", "报告期内"]:
        index = cleaned.find(marker)
        if index >= 0:
            cleaned = cleaned[index:]
            break
    cleaned = cleaned.strip("；，。:：、()（）")
    return compact_excerpt(cleaned, limit) or "年报已披露"


def annual_mdna_signal_text(row: dict[str, Any], kind: str) -> str:
    if not row:
        return "未获取"
    if kind == "performance":
        value = row.get("performance_excerpt", {})
        text = str(value.get("excerpt", ""))
        labels: list[str] = []
        if annual_mdna_has(text, ["扭亏", "恢复", "改善"]):
            labels.append("利润修复")
        if annual_mdna_has(text, ["同比增长", "增长", "提升", "增加"]):
            labels.append("收入/利润增长")
        if annual_mdna_has(text, ["下降", "承压", "亏损", "减值", "不及预期"]):
            labels.append("盈利承压")
        if annual_mdna_has(text, ["价格", "售价", "配额"]):
            labels.append("价格/配额驱动")
        if annual_mdna_has(text, ["需求", "市场", "客户", "订单"]):
            labels.append("需求/客户驱动")
        if annual_mdna_has(text, ["项目", "投产", "产能", "产品结构", "新品"]):
            labels.append("项目投产/产品结构")
        if annual_mdna_has(text, ["研发"]):
            labels.append("研发投入")
        base = "；".join(dict.fromkeys(labels[:3])) or annual_mdna_fallback_signal(value)
    elif kind == "margin_cashflow":
        margin = row.get("margin_cost_excerpt", {})
        cash = row.get("cash_working_capital_excerpt", {})
        text = str(margin.get("excerpt", "")) + str(cash.get("excerpt", ""))
        labels = []
        if "毛利率" in text and annual_mdna_has(text, ["提升", "上升", "增加", "改善"]):
            labels.append("毛利率改善")
        if "毛利率" in text and annual_mdna_has(text, ["下降", "下滑", "承压"]):
            labels.append("毛利率承压")
        if annual_mdna_has(text, ["原材料", "成本", "价格", "采购"]):
            labels.append("成本传导/原料压力")
        if annual_mdna_has(text, ["产品结构", "高毛利", "新品"]):
            labels.append("产品结构影响")
        if "现金流" in text and annual_mdna_has(text, ["增加", "改善", "好于"]):
            labels.append("经营现金流改善")
        if annual_mdna_has(text, ["下降", "减少", "占用", "存货", "应收"]):
            labels.append("营运资金占用")
        if annual_mdna_has(text, ["预收", "合同负债"]):
            labels.append("预收/合同负债线索")
        base = "；".join(dict.fromkeys(labels[:4])) or annual_mdna_fallback_signal(margin)
    elif kind == "risk":
        value = row.get("risk_excerpt", {})
        text = str(value.get("excerpt", ""))
        labels = []
        if annual_mdna_has(text, ["原材料", "供应", "采购"]):
            labels.append("原材料/供应风险")
        if annual_mdna_has(text, ["周期", "宏观", "需求", "市场"]):
            labels.append("周期/需求风险")
        if annual_mdna_has(text, ["竞争", "价格下跌", "价格波动"]):
            labels.append("价格/竞争风险")
        if annual_mdna_has(text, ["安全", "环保", "危险化学品"]):
            labels.append("安全环保风险")
        if annual_mdna_has(text, ["客户", "认证", "良率", "质量"]):
            labels.append("客户认证/质量风险")
        if annual_mdna_has(text, ["应收", "回款", "坏账"]):
            labels.append("回款风险")
        if annual_mdna_has(text, ["汇率", "利率", "融资"]):
            labels.append("金融风险")
        if annual_mdna_has(text, ["项目", "投产", "技术路线"]):
            labels.append("项目/技术路线风险")
        base = "；".join(dict.fromkeys(labels[:4])) or annual_mdna_fallback_signal(value)
    else:
        base = "未获取"
    pages = [row.get(key, {}).get("page") for key in ["performance_excerpt", "margin_cost_excerpt", "cash_working_capital_excerpt", "risk_excerpt"]]
    page_text = "/".join(str(page) for page in pages if page) if pages else ""
    return f"{base}（证据页{page_text}）" if page_text else base


