def sentiment_regime(score: float, bubble_degree: float | None) -> str:
    if bubble_degree is not None and bubble_degree > 1.0:
        return "强情绪溢价"
    if score >= 75:
        return "高热度验证期"
    if score >= 60:
        return "主题支持但需业绩"
    return "基本面主导"


def trading_context(amount: float) -> str:
    if amount >= 5e9:
        return "高成交额/拥挤"
    if amount >= 1e9:
        return "中高成交额"
    if amount > 0:
        return "流动性一般"
    return "成交额缺失"


def market_event_summary(events: list[dict[str, Any]]) -> str:
    if not events:
        return "无结构化事件"
    labels = []
    for event in events[:3]:
        event_type = str(event.get("event_type") or "event")
        direction = str(event.get("direction") or "")
        severity = str(event.get("severity") or "")
        label = event_type
        if direction:
            label += f"/{direction}"
        if severity:
            label += f"/{severity}"
        labels.append(label)
    return "；".join(labels)


def intraday_position_label(value: Any) -> str:
    try:
        pos = float(value)
    except Exception:
        return "日内位置缺失"
    if pos >= 0.75:
        return "收近高位"
    if pos <= 0.25:
        return "收近低位"
    return "区间中部"


def price_move_label(change_pct: Any) -> str:
    try:
        pct = float(change_pct)
    except Exception:
        return "涨跌幅缺失"
    if pct >= 5:
        return "单日大涨"
    if pct >= 2:
        return "上涨"
    if pct <= -5:
        return "单日大跌"
    if pct <= -2:
        return "下跌"
    return "温和波动"


def market_tape_status(row: dict[str, Any]) -> str:
    labels = [price_move_label(row.get("change_percent")), intraday_position_label(row.get("intraday_position"))]
    amount = safe_float_value(row.get("amount")) or 0.0
    if amount >= 5e9:
        labels.append("高成交额")
    elif amount >= 1e9:
        labels.append("中高成交额")
    else:
        labels.append("成交一般")
    if row.get("market_event_count"):
        labels.append("有结构化事件")
    return "；".join(labels)


def market_tape_model_use(row: dict[str, Any]) -> str:
    change = safe_float_value(row.get("change_percent"))
    amount = safe_float_value(row.get("amount")) or 0.0
    if change is not None and change <= -5:
        return "风险释放/验证公告支撑，降低追价权重"
    if change is not None and change >= 5 and amount >= 5e9:
        return "拥挤升温，只提高市场锚观察，不提高基本面锚"
    if amount >= 5e9:
        return "主题交易活跃，需用订单/价格/毛利维持市场锚"
    return "流动性和价格信号作为监测变量"


def market_tape_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    out = []
    for r in rows:
        out.append(
            {
                "ticker": r["code"],
                "company": r["name"],
                "theme": r["theme"],
                "price": r.get("price"),
                "change_percent": r.get("change_percent"),
                "intraday_high": r.get("intraday_high"),
                "intraday_low": r.get("intraday_low"),
                "intraday_range_pct": r.get("intraday_range_pct"),
                "intraday_position": r.get("intraday_position"),
                "turnover_amount": r.get("amount"),
                "turnover_rate": r.get("turnover_rate"),
                "volume_ratio": r.get("volume_ratio"),
                "market_event_count": r.get("market_event_count"),
                "market_event_summary": r.get("market_event_summary"),
                "market_tape_status": market_tape_status(r),
                "valuation_use": market_tape_model_use(r),
                "evidence_boundary": "盘口和日内行情只用于二级市场拥挤度、风险释放和市场锚监测，不替代订单、合同平均售价、收入确认或单品毛利。",
            }
        )
    return out


def market_tape_packet(rows: list[dict[str, Any]]) -> dict[str, Any]:
    tape_rows = market_tape_rows(rows)
    return {
        "schema": "astock.market_tape_snapshot.v1",
        "generated_at": now_cst(),
        "gate_status": "PASS",
        "covered_tickers": len({r["ticker"] for r in tape_rows}),
        "rows": tape_rows,
        "use_boundary": "市场盘口快照只用于交易热度、拥挤风险和市场锚权重监测，不得替代基本面目标价、客户订单、合同平均售价、收入确认比例或单品毛利。",
    }


def market_tape_md(rows: list[dict[str, Any]]) -> str:
    packet = market_tape_packet(rows)
    table_rows = [
        [
            r["ticker"],
            r["company"],
            r["theme"],
            fmt_num(r["price"], 2),
            fmt_points(r["change_percent"]),
            fmt_points((r["intraday_range_pct"] or 0) * 100 if r["intraday_range_pct"] is not None else None),
            cny_yi(r["turnover_amount"]),
            r["market_tape_status"],
            r["valuation_use"],
        ]
        for r in packet["rows"]
    ]
    return "# 市场盘口与日内风险快照\n\n门禁状态：通过。本快照把现价之外的涨跌幅、日内区间、成交额和结构化市场事件单独成包，解决“只有当前价格、缺少二级市场状态”的问题。它只进入拥挤交易、风险释放和市场锚监测，不进入基本面目标价。\n\n" + md_table(
        ["代码", "名称", "主题", "现价", "涨跌幅", "日内振幅", "成交额", "盘口状态", "估值用途"],
        table_rows,
    ) + f"\n\n- 覆盖标的：{packet['covered_tickers']}/18\n- 使用边界：{packet['use_boundary']}\n"


def eastmoney_quote_secid(code: str) -> str:
    return ("1." if code.startswith("6") else "0.") + code


def eastmoney_scaled(value: Any, divisor: float = 100.0) -> float | None:
    number = safe_float_value(value)
    if number is None:
        return None
    return number / divisor


def official_liquidity_signal(row: dict[str, Any]) -> str:
    turnover = safe_float_value(row.get("official_turnover_rate_pct")) or 0.0
    amount = safe_float_value(row.get("official_turnover_amount")) or 0.0
    float_ratio = safe_float_value(row.get("float_market_cap_ratio"))
    labels = []
    if amount >= 5e9:
        labels.append("高成交额")
    elif amount >= 1e9:
        labels.append("中高成交额")
    else:
        labels.append("成交一般")
    if turnover >= 8:
        labels.append("高换手")
    elif turnover >= 4:
        labels.append("中高换手")
    else:
        labels.append("换手温和")
    if float_ratio is not None and float_ratio < 0.45:
        labels.append("流通盘约束强")
    elif float_ratio is not None:
        labels.append("流通盘约束中性")
    return "；".join(labels)


OFFICIAL_MARKET_LIQUIDITY_VALUATION_USE = "作为估值现价、官方总市值、官方流通市值、换手率、量比和成交额主口径；官方现价进入当前价格、估值空间、市盈率/市销率/市净率和市场锚，官方总市值进入市值与市销率分母。"
OFFICIAL_MARKET_LIQUIDITY_EVIDENCE_BOUNDARY = "官方行情口径只证明二级市场价格、市值、流动性和拥挤度，不替代客户订单、合同平均售价、收入确认比例或单品毛利。"
OFFICIAL_MARKET_LIQUIDITY_USE_BOUNDARY = "东方财富官方行情快照作为估值现价、官方总市值、流通市值、换手率、量比和成交额主口径；仍不替代客户订单、合同平均售价、收入确认比例或单品毛利。"


def apply_official_market_liquidity_policy(packet: dict[str, Any], rows: list[dict[str, Any]]) -> dict[str, Any]:
    row_map = {r.get("code"): r for r in rows}
    for row in packet.get("rows", []):
        model_row = row_map.get(str(row.get("ticker")), {})
        official_total = safe_float_value(row.get("official_total_market_cap"))
        estimated = safe_float_value(model_row.get("market_cap"))
        if estimated is not None:
            row["astock_estimated_market_cap"] = estimated
        row["estimated_vs_official_delta_pct"] = (
            estimated / official_total - 1 if estimated and official_total else None
        )
        row["valuation_use"] = OFFICIAL_MARKET_LIQUIDITY_VALUATION_USE
        row["evidence_boundary"] = OFFICIAL_MARKET_LIQUIDITY_EVIDENCE_BOUNDARY
        row["liquidity_signal"] = official_liquidity_signal(row)
    packet["use_boundary"] = OFFICIAL_MARKET_LIQUIDITY_USE_BOUNDARY
    packet["covered_tickers"] = len(
        {r.get("ticker") for r in packet.get("rows", []) if r.get("official_total_market_cap")}
    )
    return packet


def official_market_liquidity_complete(packet: dict[str, Any]) -> bool:
    rows = packet.get("rows", [])
    required = {t["code"] for t in TICKERS}
    codes = {str(r.get("ticker")) for r in rows}
    if not required <= codes:
        return False
    for row in rows:
        if not row.get("official_total_market_cap") or not row.get("official_float_market_cap"):
            return False
        if row.get("official_turnover_rate_pct") is None or row.get("official_volume_ratio") is None:
            return False
    return True


def fetch_official_market_liquidity_snapshot(rows: list[dict[str, Any]]) -> dict[str, Any]:
    cache_path = CASE / "data/official_market_liquidity_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_OFFICIAL_MARKET_LIQUIDITY") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if official_market_liquidity_complete(cached):
                cached["cache_used"] = True
                return apply_official_market_liquidity_policy(cached, rows)
        except Exception:
            pass

    row_map = {r["code"]: r for r in rows}
    secids = ",".join(eastmoney_quote_secid(t["code"]) for t in TICKERS)
    fields = "f12,f14,f2,f3,f4,f5,f6,f7,f8,f9,f10,f20,f21,f100,f124"
    errors: list[dict[str, Any]] = []
    diff: list[dict[str, Any]] = []
    session = requests.Session()
    for attempt in range(3):
        try:
            response = session.get(
                "https://push2.eastmoney.com/api/qt/ulist.np/get",
                params={"secids": secids, "fields": fields},
                timeout=(5, 15),
                headers={"User-Agent": "Mozilla/5.0", "Referer": "https://quote.eastmoney.com/"},
            )
            response.raise_for_status()
            diff = (response.json().get("data") or {}).get("diff") or []
            if diff:
                break
        except Exception as exc:
            errors.append({"stage": "eastmoney_batch_quote", "attempt": attempt + 1, "error": str(exc)})
    by_code = {str(item.get("f12")): item for item in diff}
    out: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        item = by_code.get(code, {})
        model_row = row_map.get(code, {})
        official_total = safe_float_value(item.get("f20"))
        official_float = safe_float_value(item.get("f21"))
        estimated = safe_float_value(model_row.get("market_cap"))
        cap_delta = (estimated / official_total - 1) if estimated and official_total else None
        float_ratio = (official_float / official_total) if official_float and official_total else None
        ts_value = safe_float_value(item.get("f124"))
        quote_time = (
            datetime.fromtimestamp(ts_value, timezone(timedelta(hours=8))).isoformat()
            if ts_value
            else now_cst()
        )
        row = {
            "ticker": code,
            "company": ticker["name"],
            "theme": ticker["theme"],
            "quote_time": quote_time,
            "eastmoney_industry": item.get("f100") or "未获取",
            "official_price": eastmoney_scaled(item.get("f2")),
            "official_change_percent": eastmoney_scaled(item.get("f3")),
            "official_intraday_range_pct": eastmoney_scaled(item.get("f7")),
            "official_turnover_rate_pct": eastmoney_scaled(item.get("f8")),
            "official_volume_ratio": eastmoney_scaled(item.get("f10")),
            "official_volume_lot": safe_float_value(item.get("f5")),
            "official_turnover_amount": safe_float_value(item.get("f6")),
            "official_total_market_cap": official_total,
            "official_float_market_cap": official_float,
            "float_market_cap_ratio": float_ratio,
            "astock_estimated_market_cap": estimated,
            "estimated_vs_official_delta_pct": cap_delta,
            "valuation_use": OFFICIAL_MARKET_LIQUIDITY_VALUATION_USE,
            "evidence_boundary": OFFICIAL_MARKET_LIQUIDITY_EVIDENCE_BOUNDARY,
        }
        row["liquidity_signal"] = official_liquidity_signal(row)
        out.append(row)
    return {
        "schema": "astock.official_market_liquidity_snapshot.v1",
        "generated_at": now_cst(),
        "source": "eastmoney_push2_batch_quote",
        "gate_status": "CONDITIONAL",
        "covered_tickers": len({r["ticker"] for r in out if r.get("official_total_market_cap")}),
        "rows": out,
        "errors": errors,
        "use_boundary": OFFICIAL_MARKET_LIQUIDITY_USE_BOUNDARY,
    }


def official_market_liquidity_rows_by_ticker() -> dict[str, dict[str, Any]]:
    return {str(row.get("ticker")): row for row in OFFICIAL_MARKET_LIQUIDITY_SNAPSHOT.get("rows", [])}


def official_market_liquidity_md() -> str:
    rows = OFFICIAL_MARKET_LIQUIDITY_SNAPSHOT.get("rows", [])
    table_rows = [
        [
            r["ticker"],
            r["company"],
            str(r.get("quote_time", ""))[:16],
            fmt_num(r.get("official_price"), 2),
            cny_yi(r.get("official_total_market_cap")),
            cny_yi(r.get("official_float_market_cap")),
            fmt_ratio(r.get("float_market_cap_ratio")),
            fmt_ratio((r.get("official_turnover_rate_pct") or 0) / 100 if r.get("official_turnover_rate_pct") is not None else None),
            fmt_num(r.get("official_volume_ratio"), 2),
            cny_yi(r.get("official_turnover_amount")),
            fmt_ratio(r.get("estimated_vs_official_delta_pct")),
            r.get("liquidity_signal", "未获取"),
        ]
        for r in rows
    ]
    errors = OFFICIAL_MARKET_LIQUIDITY_SNAPSHOT.get("errors", [])
    err_text = "无" if not errors else "；".join(f"{e.get('stage')}#{e.get('attempt')}:{e.get('error')}" for e in errors[-3:])
    return "# 官方市值与流动性口径快照\n\n门禁状态：有条件通过。本包使用东方财富批量行情接口补齐官方现价、官方总市值、流通市值、换手率、量比、成交额和行业口径。当前估值模型以该快照作为现价和市值主口径，AStock行情能力层价格保留为审计对照；但官方行情仍只证明二级市场价格、市值和拥挤度，不替代客户订单、合同平均售价、收入确认比例或单品毛利。\n\n" + md_table(
        ["代码", "名称", "行情时间", "官方价", "官方总市值", "官方流通市值", "流通/总市值", "换手率", "量比", "成交额", "估算/官方差异", "流动性信号"],
        table_rows,
    ) + f"\n\n- 覆盖标的：{OFFICIAL_MARKET_LIQUIDITY_SNAPSHOT.get('covered_tickers', len(rows))}/18\n- 抓取错误：{err_text}\n- 缓存使用：{bool(OFFICIAL_MARKET_LIQUIDITY_SNAPSHOT.get('cache_used'))}\n- 使用边界：{OFFICIAL_MARKET_LIQUIDITY_SNAPSHOT.get('use_boundary', '')}\n"


def dataframe_to_records(df: Any) -> list[dict[str, Any]]:
    if df is None:
        return []
    try:
        raw_records = df.to_dict("records")
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for record in raw_records:
        clean: dict[str, Any] = {}
        for key, value in record.items():
            value = clean_cell(value)
            if hasattr(value, "item"):
                try:
                    value = value.item()
                except Exception:
                    value = str(value)
            if value is not None and not isinstance(value, (str, int, float, bool)):
                value = str(value)
            clean[str(key)] = value
        out.append(clean)
    return out


def latest_records(records: list[dict[str, Any]], date_keys: list[str]) -> list[dict[str, Any]]:
    dated: list[tuple[str, dict[str, Any]]] = []
    for record in records:
        date_value = ""
        for key in date_keys:
            if record.get(key):
                date_value = str(record.get(key))
                break
        if date_value:
            dated.append((date_value, record))
    if not dated:
        return []
    latest = max(date for date, _ in dated)
    return [record for date, record in dated if date == latest]


def latest_date_value(records: list[dict[str, Any]], date_keys: list[str]) -> str:
    latest = latest_records(records, date_keys)
    if not latest:
        return "未获取"
    for key in date_keys:
        if latest[0].get(key):
            return str(latest[0].get(key))
    return "未获取"


def sort_by_rank(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return sorted(records, key=lambda r: safe_float_value(r.get("编号")) or 999)


def sum_share(records: list[dict[str, Any]], key: str, n: int = 10) -> float | None:
    values = [safe_float_value(r.get(key)) for r in sort_by_rank(records)[:n]]
    values = [v for v in values if v is not None]
    if not values:
        return None
    return sum(values)


def holder_names(records: list[dict[str, Any]], key: str, n: int = 3) -> str:
    names = [str(r.get(key) or "").strip() for r in sort_by_rank(records)[:n] if str(r.get(key) or "").strip()]
    return "、".join(names[:n]) if names else "未获取"


def ownership_structure_label(top1_name: str, top1_pct: float | None, top10_pct: float | None) -> str:
    name = top1_name or ""
    if top1_pct is not None and top1_pct >= 50:
        return "控股股东高度集中"
    if any(token in name for token in ["国资", "中国", "中船", "厦门", "中钨", "集团", "控股"]) and top1_pct is not None and top1_pct >= 25:
        return "产业/国资控股约束强"
    if top10_pct is not None and top10_pct >= 50:
        return "前十股东集中"
    return "股权结构相对分散"


def shareholder_crowding_signal(row: dict[str, Any]) -> str:
    score = 0
    labels: list[str] = []
    turnover = safe_float_value(row.get("official_turnover_rate_pct")) or 0.0
    amount = safe_float_value(row.get("official_turnover_amount")) or 0.0
    float_ratio = safe_float_value(row.get("float_market_cap_ratio"))
    fund_pct = safe_float_value(row.get("fund_float_share_pct")) or 0.0
    circulate_top10 = safe_float_value(row.get("circulate_top10_float_share_pct")) or 0.0
    if turnover >= 10:
        score += 3
        labels.append("高换手")
    elif turnover >= 5:
        score += 2
        labels.append("中高换手")
    if amount >= 5e9:
        score += 1
        labels.append("高成交额")
    if float_ratio is not None and float_ratio < 0.5:
        score += 2
        labels.append("低流通占比")
    if fund_pct >= 5:
        score += 2
        labels.append("基金持仓拥挤")
    elif fund_pct >= 2:
        score += 1
        labels.append("基金持仓中等")
    if circulate_top10 >= 40:
        score += 2
        labels.append("流通前十集中")
    elif circulate_top10 >= 25:
        score += 1
        labels.append("流通前十中等集中")
    if score >= 6:
        risk = "高拥挤"
    elif score >= 3:
        risk = "中拥挤"
    else:
        risk = "低拥挤"
    return risk + "：" + ("；".join(labels) if labels else "机构和换手信号温和")


def shareholder_model_action(signal: str) -> str:
    if signal.startswith("高拥挤"):
        return "下调追价容忍度，市场锚需订单/业绩继续验证"
    if signal.startswith("中拥挤"):
        return "维持市场锚，但提高公告和财报验证频率"
    return "只作为流动性和机构参与度参考"


def shareholder_crowding_complete(packet: dict[str, Any]) -> bool:
    rows = packet.get("rows", [])
    required = {t["code"] for t in TICKERS}
    codes = {str(r.get("ticker")) for r in rows}
    if not required <= codes:
        return False
    required_keys = [
        "ticker",
        "company",
        "top_holder_date",
        "top1_holder",
        "top1_share_pct",
        "main_top10_share_pct",
        "circulate_top10_float_share_pct",
        "fund_holder_count",
        "fund_float_share_pct",
        "official_turnover_rate_pct",
        "crowding_signal",
        "model_action",
    ]
    for row in rows:
        for key in required_keys:
            if row.get(key) in (None, "", []):
                return False
    return True


def fetch_shareholder_crowding_snapshot(rows: list[dict[str, Any]]) -> dict[str, Any]:
    cache_path = CASE / "data/shareholder_crowding_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_SHAREHOLDER_CROWDING") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if cached.get("schema") == "astock.shareholder_crowding_snapshot.v1" and shareholder_crowding_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass

    try:
        import akshare as ak  # noqa: PLC0415
    except Exception as exc:
        return {
            "schema": "astock.shareholder_crowding_snapshot.v1",
            "generated_at": now_cst(),
            "source": "akshare_sina_shareholder_and_fund_holding",
            "gate_status": "BLOCKED",
            "covered_tickers": 0,
            "rows": [],
            "errors": [{"stage": "import_akshare", "error": str(exc)}],
            "use_boundary": "股东/基金持仓只用于二级市场拥挤度和市场锚约束，不替代客户订单、合同ASP、收入确认比例或单品毛利。",
        }

    row_map = {r["code"]: r for r in rows}
    official_map = official_market_liquidity_rows_by_ticker()
    out: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        main_records: list[dict[str, Any]] = []
        circulate_records: list[dict[str, Any]] = []
        fund_records: list[dict[str, Any]] = []
        try:
            main_records = dataframe_to_records(ak.stock_main_stock_holder(stock=code))
        except Exception as exc:
            errors.append({"ticker": code, "stage": "main_stock_holder", "error": str(exc)})
        try:
            circulate_records = dataframe_to_records(ak.stock_circulate_stock_holder(symbol=code))
        except Exception as exc:
            errors.append({"ticker": code, "stage": "circulate_stock_holder", "error": str(exc)})
        try:
            fund_records = dataframe_to_records(ak.stock_fund_stock_holder(symbol=code))
        except Exception as exc:
            errors.append({"ticker": code, "stage": "fund_stock_holder", "error": str(exc)})

        latest_main = sort_by_rank(latest_records(main_records, ["截至日期", "截止日期"]))
        latest_circulate = sort_by_rank(latest_records(circulate_records, ["截止日期", "截至日期"]))
        latest_fund = latest_records(fund_records, ["截止日期", "截至日期"])
        top1 = latest_main[0] if latest_main else {}
        top1_name = str(top1.get("股东名称") or "未获取")
        top1_pct = safe_float_value(top1.get("持股比例")) or 0.0
        main_top10_pct = sum_share(latest_main, "持股比例") or 0.0
        circulate_top10_pct = sum_share(latest_circulate, "占流通股比例") or 0.0
        fund_float_pct = sum(safe_float_value(r.get("占流通股比例")) or 0.0 for r in latest_fund)
        fund_market_value = sum(safe_float_value(r.get("持股市值")) or 0.0 for r in latest_fund)
        official = official_map.get(code, {})
        model = row_map.get(code, {})
        record = {
            "ticker": code,
            "company": ticker["name"],
            "theme": ticker["theme"],
            "top_holder_date": latest_date_value(main_records, ["截至日期", "截止日期"]),
            "top1_holder": top1_name,
            "top1_share_pct": top1_pct,
            "top1_share_type": str(top1.get("股本性质") or "未获取"),
            "main_top5_share_pct": sum_share(latest_main, "持股比例", 5) or 0.0,
            "main_top10_share_pct": main_top10_pct,
            "shareholder_count": safe_float_value(top1.get("股东总数")),
            "average_holding": safe_float_value(top1.get("平均持股数")),
            "ownership_structure": ownership_structure_label(top1_name, top1_pct, main_top10_pct),
            "top3_holders": holder_names(latest_main, "股东名称", 3),
            "circulate_holder_date": latest_date_value(circulate_records, ["截止日期", "截至日期"]),
            "circulate_top10_float_share_pct": circulate_top10_pct,
            "top3_circulate_holders": holder_names(latest_circulate, "股东名称", 3),
            "fund_holder_date": latest_date_value(fund_records, ["截止日期", "截至日期"]),
            "fund_holder_count": len(latest_fund),
            "fund_float_share_pct": fund_float_pct,
            "fund_market_value": fund_market_value,
            "top3_funds": holder_names(latest_fund, "基金名称", 3),
            "official_float_market_cap": official.get("official_float_market_cap"),
            "float_market_cap_ratio": official.get("float_market_cap_ratio"),
            "official_turnover_rate_pct": official.get("official_turnover_rate_pct"),
            "official_turnover_amount": official.get("official_turnover_amount"),
            "current_price": model.get("price"),
            "final_target": model.get("final_target"),
            "valuation_use": "用于股权集中度、基金拥挤度、流通盘压力和市场锚风险；不进入收入、毛利或基本面目标价上修。",
            "evidence_boundary": "股东和基金持仓披露只证明二级市场持有人结构和流通盘拥挤度，不替代客户订单、合同平均售价、收入确认比例、客户份额或单品毛利。",
            "source": "akshare.stock_main_stock_holder; stock_circulate_stock_holder; stock_fund_stock_holder; eastmoney official liquidity snapshot",
        }
        record["crowding_signal"] = shareholder_crowding_signal(record)
        record["model_action"] = shareholder_model_action(record["crowding_signal"])
        out.append(record)
    return {
        "schema": "astock.shareholder_crowding_snapshot.v1",
        "generated_at": now_cst(),
        "source": "akshare_sina_shareholder_and_fund_holding",
        "gate_status": "CONDITIONAL",
        "covered_tickers": len({r["ticker"] for r in out}),
        "rows": out,
        "errors": errors,
        "use_boundary": "股东/基金持仓只用于二级市场拥挤度、流通盘压力和市场锚约束，不替代客户订单、合同ASP、收入确认比例、客户份额或单品毛利。",
    }


