def margin_trade_date_candidates(days: int = 7) -> list[str]:
    base = datetime.strptime(DATE, "%Y%m%d").date()
    out: list[str] = []
    for offset in range(days + 3):
        d = base - timedelta(days=offset)
        if d.weekday() < 5:
            out.append(d.strftime("%Y%m%d"))
        if len(out) >= days:
            break
    return out


def fetch_szse_margin_detail(date: str) -> list[dict[str, Any]]:
    url = "https://www.szse.cn/api/report/ShowReport"
    params = {
        "SHOWTYPE": "xlsx",
        "CATALOGID": "1837_xxpl",
        "txtDate": "-".join([date[:4], date[4:6], date[6:]]),
        "tab2PAGENO": "1",
        "random": "0.24279342734085696",
        "TABKEY": "tab2",
    }
    headers = {
        "Referer": "https://www.szse.cn/disclosure/margin/margin/index.html",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    }
    response = requests.get(url, params=params, headers=headers, timeout=20)
    response.raise_for_status()
    if not response.content.startswith(b"PK"):
        raise ValueError("SZSE margin response is not an xlsx payload")
    import pandas as pd  # noqa: PLC0415

    with pd.option_context("mode.chained_assignment", None):
        df = pd.read_excel(BytesIO(response.content), engine="openpyxl", dtype={"证券代码": str})
    df.columns = [
        "证券代码",
        "证券简称",
        "融资买入额",
        "融资余额",
        "融券卖出量",
        "融券余量",
        "融券余额",
        "融资融券余额",
    ]
    for column in ["融资买入额", "融资余额", "融券卖出量", "融券余量", "融券余额", "融资融券余额"]:
        df[column] = pd.to_numeric(df[column].astype(str).str.replace(",", "", regex=False), errors="coerce")
    df["信用交易日期"] = date
    return dataframe_to_records(df)


def fetch_margin_detail_by_exchange() -> tuple[dict[str, dict[str, Any]], dict[str, str], list[dict[str, Any]]]:
    try:
        import akshare as ak  # noqa: PLC0415
    except Exception as exc:
        return {}, {}, [{"stage": "import_akshare", "error": str(exc)}]

    records: dict[str, dict[str, Any]] = {}
    dates: dict[str, str] = {}
    errors: list[dict[str, Any]] = []
    for date in margin_trade_date_candidates():
        try:
            sse_records = dataframe_to_records(ak.stock_margin_detail_sse(date=date))
            if sse_records:
                for record in sse_records:
                    code = str(record.get("标的证券代码") or "")
                    if code:
                        records[code] = {**record, "_exchange": "上交所", "_date": date}
                dates["上交所"] = date
                break
        except Exception as exc:
            errors.append({"stage": "sse_margin_detail", "date": date, "error": str(exc)})
    for date in margin_trade_date_candidates():
        try:
            szse_records = fetch_szse_margin_detail(date)
            if szse_records:
                for record in szse_records:
                    code = str(record.get("证券代码") or "")
                    if code:
                        records[code] = {**record, "_exchange": "深交所", "_date": date}
                dates["深交所"] = date
                break
        except Exception as exc:
            errors.append({"stage": "szse_margin_detail", "date": date, "error": str(exc)})
    return records, dates, errors


def margin_leverage_signal(row: dict[str, Any]) -> str:
    if not row.get("margin_eligible"):
        return "非两融标的：当日明细未覆盖"
    score = 0
    labels: list[str] = []
    balance_ratio = safe_float_value(row.get("margin_balance_to_float_cap")) or 0.0
    buy_ratio = safe_float_value(row.get("margin_buy_to_turnover")) or 0.0
    net_buy = safe_float_value(row.get("margin_net_buy"))
    if balance_ratio >= 0.08:
        score += 3
        labels.append("融资余额/流通市值高")
    elif balance_ratio >= 0.05:
        score += 2
        labels.append("融资余额占比较高")
    elif balance_ratio >= 0.03:
        score += 1
        labels.append("融资余额占比中等")
    if buy_ratio >= 0.30:
        score += 3
        labels.append("融资买入占成交额高")
    elif buy_ratio >= 0.20:
        score += 2
        labels.append("融资买入活跃")
    elif buy_ratio >= 0.10:
        score += 1
        labels.append("融资参与温和")
    if net_buy is not None and net_buy >= 1e8:
        score += 1
        labels.append("当日融资净买入")
    if score >= 5:
        risk = "高杠杆拥挤"
    elif score >= 3:
        risk = "中杠杆拥挤"
    else:
        risk = "低杠杆压力"
    return risk + "：" + ("；".join(labels) if labels else "融资信号温和")


def margin_model_action(signal: str) -> str:
    if signal.startswith("高杠杆"):
        return "下调追价容忍度，优先等公告/财报验证"
    if signal.startswith("中杠杆"):
        return "保留市场锚，但提高杠杆回撤监测频率"
    if signal.startswith("非两融"):
        return "不作为杠杆拥挤交易，但保留流动性观察"
    return "只作为资金结构参考，不调整基本面目标价"


