def fetch_margin_leverage_snapshot(rows: list[dict[str, Any]]) -> dict[str, Any]:
    cache_path = CASE / "data/margin_leverage_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_MARGIN_LEVERAGE") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if cached.get("schema") == "astock.margin_leverage_snapshot.v1" and margin_leverage_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass

    detail_map, exchange_dates, errors = fetch_margin_detail_by_exchange()
    official_map = official_market_liquidity_rows_by_ticker()
    row_map = {r["code"]: r for r in rows}
    out: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        record = detail_map.get(code, {})
        exchange = "上交所" if code.startswith("6") else "深交所"
        official = official_map.get(code, {})
        model = row_map.get(code, {})
        if exchange == "上交所":
            margin_balance = safe_float_value(record.get("融资余额")) or 0.0
            margin_buy = safe_float_value(record.get("融资买入额")) or 0.0
            margin_repay = safe_float_value(record.get("融资偿还额"))
            short_volume = safe_float_value(record.get("融券余量")) or 0.0
            short_balance = None
            stock_name = str(record.get("标的证券简称") or ticker["name"])
        else:
            margin_balance = safe_float_value(record.get("融资余额")) or 0.0
            margin_buy = safe_float_value(record.get("融资买入额")) or 0.0
            margin_repay = None
            short_volume = safe_float_value(record.get("融券余量")) or 0.0
            short_balance = safe_float_value(record.get("融券余额"))
            stock_name = str(record.get("证券简称") or ticker["name"])
        float_cap = safe_float_value(official.get("official_float_market_cap")) or 0.0
        turnover = safe_float_value(official.get("official_turnover_amount")) or 0.0
        margin_net_buy = margin_buy - margin_repay if margin_repay is not None else None
        item = {
            "ticker": code,
            "company": ticker["name"],
            "exchange": exchange,
            "margin_date": str(record.get("_date") or exchange_dates.get(exchange) or "未获取"),
            "margin_status": "两融标的" if record else "非两融标的或当日明细未覆盖",
            "margin_eligible": bool(record),
            "exchange_stock_name": stock_name,
            "margin_balance": margin_balance,
            "margin_buy": margin_buy,
            "margin_repay": margin_repay,
            "margin_net_buy": margin_net_buy,
            "short_volume": short_volume,
            "short_balance": short_balance,
            "official_float_market_cap": float_cap,
            "official_turnover_amount": turnover,
            "margin_balance_to_float_cap": margin_balance / float_cap if float_cap else 0.0,
            "margin_buy_to_turnover": margin_buy / turnover if turnover else 0.0,
            "current_price": model.get("price"),
            "final_target": model.get("final_target"),
            "valuation_use": "只用于识别杠杆资金参与度、回撤放大风险和市场锚压力，不进入基本面目标价上修。",
            "evidence_boundary": "融资融券明细只证明杠杆资金和融券交易状态，不替代客户订单、合同平均售价、收入确认比例、客户份额或单品毛利。",
            "source": "SSE margin detail API; SZSE margin xlsx API with BytesIO fallback; Eastmoney official liquidity snapshot",
        }
        item["leverage_signal"] = margin_leverage_signal(item)
        item["model_action"] = margin_model_action(item["leverage_signal"])
        out.append(item)
    return {
        "schema": "astock.margin_leverage_snapshot.v1",
        "generated_at": now_cst(),
        "source": "sse_szse_margin_detail_public_apis",
        "gate_status": "CONDITIONAL",
        "covered_tickers": len({r["ticker"] for r in out}),
        "margin_eligible_tickers": len([r for r in out if r.get("margin_eligible")]),
        "exchange_dates": exchange_dates,
        "rows": out,
        "errors": errors,
        "use_boundary": "两融明细只用于杠杆资金拥挤度、回撤放大风险和市场锚约束，不替代客户订单、合同平均售价、收入确认比例、客户份额或单品毛利。",
    }


