def lhb_month_date_range() -> tuple[str, str]:
    base = datetime.strptime(DATE, "%Y%m%d").date()
    return base.replace(day=1).strftime("%Y%m%d"), base.strftime("%Y%m%d")


def normalize_code(value: Any) -> str:
    return str(value or "").strip().split(".")[0].zfill(6)


def dataframe_records_by_code(df: Any, code_col: str = "代码") -> dict[str, dict[str, Any]]:
    records: dict[str, dict[str, Any]] = {}
    for record in dataframe_to_records(df):
        code = normalize_code(record.get(code_col))
        if code:
            records[code] = record
    return records


def dragon_tiger_signal(row: dict[str, Any]) -> str:
    month_count = int(safe_float_value(row.get("month_list_count")) or 0)
    net_buy = safe_float_value(row.get("month_lhb_net_buy")) or 0.0
    institution_net = safe_float_value(row.get("month_institution_net_buy")) or 0.0
    detail_count = int(safe_float_value(row.get("june_detail_count")) or 0)
    labels: list[str] = []
    score = 0
    if month_count >= 5:
        score += 3
        labels.append("高频上榜")
    elif month_count >= 2:
        score += 2
        labels.append("多次上榜")
    elif month_count == 1:
        score += 1
        labels.append("单次上榜")
    if abs(net_buy) >= 1e9:
        score += 2
        labels.append("龙虎榜净额波动大")
    elif abs(net_buy) >= 3e8:
        score += 1
        labels.append("龙虎榜净额显著")
    if institution_net >= 3e8:
        score += 2
        labels.append("机构净买入")
    elif institution_net <= -3e8:
        score += 2
        labels.append("机构净卖出")
    elif abs(institution_net) >= 1e8:
        score += 1
        labels.append("机构分歧")
    if detail_count >= 5:
        score += 1
        labels.append("6月明细密集")
    if score >= 6:
        level = "高席位拥挤"
    elif score >= 3:
        level = "中席位拥挤"
    elif score > 0:
        level = "低席位扰动"
    else:
        return "近一月未上榜：无公开异常席位信号"
    return level + "：" + "；".join(labels)


def dragon_tiger_model_action(signal: str) -> str:
    if signal.startswith("高席位"):
        return "下调追价容忍度，优先等待公告/财报验证"
    if signal.startswith("中席位"):
        return "保留市场锚，但提高席位和回撤监测频率"
    if signal.startswith("低席位"):
        return "只作为交易扰动参考，不调整基本面目标价"
    return "无公开异常席位，不作为交易热度加分"


def dragon_tiger_complete(packet: dict[str, Any]) -> bool:
    rows = packet.get("rows", [])
    required = {t["code"] for t in TICKERS}
    codes = {str(r.get("ticker")) for r in rows}
    if not required <= codes:
        return False
    required_keys = [
        "ticker",
        "company",
        "month_status",
        "latest_lhb_date",
        "month_list_count",
        "month_lhb_net_buy",
        "month_lhb_turnover",
        "month_institution_net_buy",
        "june_detail_count",
        "seat_signal",
        "model_action",
        "evidence_boundary",
    ]
    for row in rows:
        for key in required_keys:
            if row.get(key) in (None, "", []):
                return False
    return True


def fetch_dragon_tiger_seat_snapshot(rows: list[dict[str, Any]]) -> dict[str, Any]:
    cache_path = CASE / "data/dragon_tiger_seat_snapshot.json"
    if os.getenv("ASTOCK_REFRESH_DRAGON_TIGER") != "1" and cache_path.exists():
        try:
            cached = json.loads(cache_path.read_text(encoding="utf-8"))
            if cached.get("schema") == "astock.dragon_tiger_seat_snapshot.v1" and dragon_tiger_complete(cached):
                cached["cache_used"] = True
                return cached
        except Exception:
            pass

    errors: list[dict[str, Any]] = []
    month_map: dict[str, dict[str, Any]] = {}
    institution_map: dict[str, dict[str, Any]] = {}
    detail_records: list[dict[str, Any]] = []
    try:
        import akshare as ak  # noqa: PLC0415

        month_map = dataframe_records_by_code(ak.stock_lhb_stock_statistic_em(symbol="近一月"))
        institution_map = dataframe_records_by_code(ak.stock_lhb_jgstatistic_em(symbol="近一月"))
        start_date, end_date = lhb_month_date_range()
        detail_records = [
            record
            for record in dataframe_to_records(ak.stock_lhb_detail_em(start_date=start_date, end_date=end_date))
            if normalize_code(record.get("代码")) in {t["code"] for t in TICKERS}
        ]
    except Exception as exc:
        errors.append({"stage": "fetch_dragon_tiger", "error": str(exc)})

    detail_by_code: dict[str, list[dict[str, Any]]] = {}
    for record in detail_records:
        detail_by_code.setdefault(normalize_code(record.get("代码")), []).append(record)

    out: list[dict[str, Any]] = []
    for ticker in TICKERS:
        code = ticker["code"]
        month = month_map.get(code, {})
        institution = institution_map.get(code, {})
        details = detail_by_code.get(code, [])
        reasons = sorted({str(d.get("上榜原因") or "") for d in details if d.get("上榜原因")})
        interpretations = sorted({str(d.get("解读") or "") for d in details if d.get("解读")})
        item = {
            "ticker": code,
            "company": ticker["name"],
            "month_status": "近一月上榜" if month else "近一月未上榜",
            "latest_lhb_date": str(month.get("最近上榜日") or (details[0].get("上榜日") if details else "未上榜")),
            "month_list_count": int(safe_float_value(month.get("上榜次数")) or 0),
            "month_lhb_net_buy": safe_float_value(month.get("龙虎榜净买额")) or 0.0,
            "month_lhb_buy": safe_float_value(month.get("龙虎榜买入额")) or 0.0,
            "month_lhb_sell": safe_float_value(month.get("龙虎榜卖出额")) or 0.0,
            "month_lhb_turnover": safe_float_value(month.get("龙虎榜总成交额")) or 0.0,
            "buyer_institution_count": int(safe_float_value(month.get("买方机构次数")) or 0),
            "seller_institution_count": int(safe_float_value(month.get("卖方机构次数")) or 0),
            "month_institution_net_buy": safe_float_value(institution.get("机构净买额")) if institution else safe_float_value(month.get("机构买入净额")) or 0.0,
            "institution_buy_amount": safe_float_value(institution.get("机构买入额")) or safe_float_value(month.get("机构买入总额")) or 0.0,
            "institution_sell_amount": safe_float_value(institution.get("机构卖出额")) or safe_float_value(month.get("机构卖出总额")) or 0.0,
            "june_detail_count": len(details),
            "june_latest_reason": reasons[0] if reasons else "无6月龙虎榜明细",
            "june_interpretation": "；".join(interpretations[:2]) if interpretations else "无公开席位解读",
            "valuation_use": "只用于识别异常交易席位、机构净买卖和短期交易拥挤，不进入基本面目标价上修。",
            "evidence_boundary": "龙虎榜只披露符合异常交易条件后的公开席位，不是实时逐笔席位、全市场资金流，也不替代客户订单、合同平均售价、收入确认比例、客户份额或单品毛利。",
            "source": "AkShare Eastmoney stock_lhb_stock_statistic_em/jgstatistic/detail_em public interfaces",
        }
        item["seat_signal"] = dragon_tiger_signal(item)
        item["model_action"] = dragon_tiger_model_action(item["seat_signal"])
        out.append(item)
    return {
        "schema": "astock.dragon_tiger_seat_snapshot.v1",
        "generated_at": now_cst(),
        "source": "eastmoney_dragon_tiger_public_interfaces",
        "gate_status": "CONDITIONAL",
        "covered_tickers": len({r["ticker"] for r in out}),
        "recent_listed_tickers": len([r for r in out if r.get("month_status") == "近一月上榜"]),
        "june_detail_records": len(detail_records),
        "date_range": {"start": lhb_month_date_range()[0], "end": lhb_month_date_range()[1]},
        "rows": out,
        "errors": errors,
        "use_boundary": "龙虎榜席位只用于异常交易、机构净买卖、追价容忍度和回撤风险监测；未上榜不代表无资金参与，上榜也不证明基本面兑现，不替代客户订单、合同平均售价、收入确认比例、客户份额或单品毛利。",
    }


