def single_product_revenue_boundary_packet() -> dict[str, Any]:
    rows = single_product_revenue_boundary_rows()
    covered = sorted({r["ticker"] for r in rows})
    amount_rows = [
        r
        for r in rows
        if "亿元" in r.get("quantified_value", "") and "部分补证" in r.get("p0_status", "")
    ]
    quantified_rows = [
        r
        for r in rows
        if r.get("quantified_value") and not str(r.get("quantified_value")).startswith("未披露")
    ]
    return {
        "schema": "astock.official_single_product_revenue_boundary.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "covered_tickers": len(covered),
        "covered_ticker_list": covered,
        "rows": rows,
        "quantified_rows": len(quantified_rows),
        "single_product_amount_rows": len(amount_rows),
        "revenue_ratio_rows": sum(1 for r in rows if "收入占比" in r.get("official_metric", "") or "收入占比" in r.get("quantified_value", "")),
        "negative_boundary_rows": sum(1 for r in rows if "负面边界" in r.get("p0_status", "")),
        "use_boundary": "官方单品收入/订单金额边界包把昊华WF6收入占比、中船WF6/NF3历史合同金额、电子气体平台合同、招股书历史产销和中巨芯/华特/和远负面边界放到同一张表；它只能收窄P0缺口和定义估值纪律，不关闭合同ASP、收入确认比例、客户份额或单品毛利。",
    }


def single_product_revenue_boundary_pdf_metric(value: Any) -> str:
    text = reader_text(value)
    if "269.19/533.75/838.27/550.15吨" in text:
        return "历史销量约269-838吨"
    return text


def single_product_revenue_boundary_pdf_rows() -> list[list[Any]]:
    return [
        [
            r["ticker"],
            r["company"],
            r["product_scope"],
            single_product_revenue_boundary_pdf_metric(r["quantified_value"]),
            reader_text(r["what_it_proves"]),
            reader_text(r["p0_status"]),
            reader_text(r["still_missing"]),
        ]
        for r in single_product_revenue_boundary_rows()
    ]


def single_product_revenue_boundary_md() -> str:
    packet = SINGLE_PRODUCT_REVENUE_BOUNDARY_SNAPSHOT if SINGLE_PRODUCT_REVENUE_BOUNDARY_SNAPSHOT.get("rows") else single_product_revenue_boundary_packet()
    return "# 官方单品收入/订单金额边界证据\n\n" + textwrap.dedent(
        f"""\
        门禁状态：{packet['gate_status']}。本包把分散在公司澄清、合同公告扫描和中船特气招股书中的单品级量化字段集中展示，专门回答“单品收入/订单金额到底补到了哪一步”。结论是：中船特气已有WF6/NF3历史合同金额样本，昊华科技已有WF6收入占比边界，和远气体、中巨芯-U、华特气体存在明确负面或低贡献边界；但合同ASP、收入确认比例、客户份额和单品毛利仍未关闭。

        - 覆盖标的：{packet['covered_tickers']}只。
        - 有量化字段行：{packet['quantified_rows']}条。
        - 主题单品订单金额样本：{packet['single_product_amount_rows']}条。
        - 收入占比样本：{packet['revenue_ratio_rows']}条。
        - 负面边界行：{packet['negative_boundary_rows']}条。
        - 使用边界：{packet['use_boundary']}
        """
    ) + "\n" + md_table(
        ["代码", "名称", "单品/范围", "官方量化字段", "可证明", "估值用途", "仍缺字段", "P0状态", "来源"],
        [
            [
                r["ticker"],
                r["company"],
                r["product_scope"],
                r["official_metric"],
                r["what_it_proves"],
                r["valuation_use"],
                r["still_missing"],
                r["p0_status"],
                "；".join(r["source_ids"]),
            ]
            for r in packet["rows"]
        ],
    )


