def fluorinated_electronic_material_boundary_packet() -> dict[str, Any]:
    rows = fluorinated_electronic_material_boundary_rows()
    return {
        "schema": "astock.fluorinated_electronic_material_boundary.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "rows": rows,
        "covered_tickers": len(rows),
        "refrigerant_base_cashflow_allowed_count": sum(1 for r in rows if "REFRIGERANT" in r["model_gate"] or r["model_gate"] == "INTEGRATED_FLUOROCHEM_BASE_ONLY"),
        "growth_eps_allowed_count": 0,
        "use_boundary": "本包专门审计氟化工公司能否把制冷剂/HFC配额、氟化工主业或有机氟平台升级为含氟电子材料第二曲线成长信用。当前结论为0/6可进入含氟电子材料增长EPS；HFC配额和制冷剂价差可进入基准现金流，但不得替代电子材料客户、订单、单品价差、收入占比或单品毛利。",
    }


