def resource_security_evidence_packet() -> dict[str, Any]:
    rows = resource_security_evidence_rows()
    return {
        "schema": "astock.resource_security_evidence.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "rows": rows,
        "covered_tickers": len(rows),
        "resource_base_allowed_count": sum("ALLOWED" in r["model_gate"] and "OPTIONALITY" not in r["model_gate"] for r in rows),
        "growth_eps_allowed_count": 0,
        "use_boundary": "本包把钨、萤石、AHF和HFC配额的资源/供给安全证据压成基准业务门禁；资源和配额可进入基准现金流或资源安全溢价，但不关闭半导体高纯钨材、WF6/NF3或含氟电子材料的订单、平均售价、收入和毛利缺口。",
    }


def resource_security_gate_cn(model_gate: str) -> str:
    return {
        "RESOURCE_BASE_CASHFLOW_ALLOWED": "资源基准现金流可入模",
        "RESOURCE_AND_PROCESSING_BASE_ALLOWED": "资源与加工基准现金流可入模",
        "POWDER_PROCESSING_BASE_ALLOWED": "粉末加工基准现金流可入模",
        "PROCESSING_OPTIONALITY_ONLY": "加工弹性观察，资源溢价折扣",
        "FLUORITE_AHF_BASE_CASHFLOW_ALLOWED": "萤石/AHF基准现金流可入模",
        "REFRIGERANT_QUOTA_BASE_CASHFLOW_ALLOWED": "制冷剂配额基准现金流可入模",
        "INTEGRATED_FLUOROCHEM_BASE_ALLOWED": "一体化氟化工基准现金流可入模",
    }.get(model_gate, model_gate)


def resource_security_evidence_pdf_rows() -> list[list[Any]]:
    return [
        [
            r["ticker"],
            r["company"],
            r["resource_layer"],
            r["resource_or_quota_anchor"],
            r["production_sales_anchor"],
            r["valuation_use"],
            r["remaining_gap"],
        ]
        for r in resource_security_evidence_rows()
    ]


def resource_security_evidence_md() -> str:
    packet = RESOURCE_SECURITY_EVIDENCE_SNAPSHOT if RESOURCE_SECURITY_EVIDENCE_SNAPSHOT.get("rows") else resource_security_evidence_packet()
    rows = packet.get("rows", [])
    return "# 上游资源安全与基准现金流证据\n\n" + textwrap.dedent(
        f"""\
        门禁状态：有条件通过。本包把钨矿山/钨精矿、APT/粉末加工、萤石/AHF、制冷剂HFC配额和一体化氟化工证据合并，回答“上游利润池是否有可量化兑现基础”。结论是：钨资源、萤石/AHF和制冷剂配额可以进入基准业务现金流或资源安全溢价；但这些证据仍不得替代半导体高纯钨材、WF6/NF3或含氟电子材料的客户订单、合同平均售价、收入确认比例、单品收入和单品毛利。

        - 覆盖标的：{packet.get('covered_tickers', len(rows))}只。
        - 可进入资源/配额基准现金流：{packet.get('resource_base_allowed_count', 0)}/8。
        - 可进入半导体或电子材料增长每股收益：{packet.get('growth_eps_allowed_count', 0)}/8。
        - 使用边界：{packet.get('use_boundary', '')}
        """
    ) + "\n" + md_table(
        ["代码", "名称", "主题", "资源/配额层", "资源或配额锚", "产销锚", "成本/毛利锚", "估值用途", "门禁", "仍缺字段"],
        [
            [
                r["ticker"],
                r["company"],
                r["theme"],
                r["resource_layer"],
                r["resource_or_quota_anchor"],
                r["production_sales_anchor"],
                r["cost_or_margin_anchor"],
                r["valuation_use"],
                resource_security_gate_cn(r["model_gate"]),
                r["remaining_gap"],
            ]
            for r in rows
        ],
    )


def implied_growth_sensitivity_md(rows: list[dict[str, Any]]) -> str:
    sensitivity_rows = [
        ["销量/订单转换", "无长单或仅市场传闻", "产能/认证存在但订单金额未披露", "公告级客户、订单量和交付节奏披露", "决定是否从观察信用转为收入信用"],
        ["ASP/价格", "公司未披露价格", "公开价格代理已补但合同价未证实", "合同ASP或价格区间披露", "决定收入桥能否从定性转为定量"],
        ["收入确认比例", "无法判断产能利用率和交付比例", "小批量验证或试用阶段", "批量供货并可映射季度收入", "决定产能能否进入2026E收入"],
        ["毛利率", "产品毛利未披露", "平台毛利可参考但单品不清楚", "分产品毛利或毛利改善进入财报", "决定收入能否进入EPS"],
        ["估值倍数", "仅给观察/期权信用", "保留市场锚但不提高基本面锚", "可给PEG/PSG/SOTP成长信用", "决定最终目标权重是否上调"],
    ]
    ticker_rows = [
        [x["ticker"], x["company"], x["current_price_implied_growth"], x["sensitivity_key"], x["evidence_gap"]]
        for x in growth_driver_rows(rows)
        if x["applies"]
    ]
    price_rows = [
        [r["theme"], r["proxy_item"], r["value"], r["trend"], r["valuation_use"], r["remaining_gap"]]
        for r in public_price_proxy_rows()
        if r.get("theme") in {"钨", "电子特气", "氟化工"}
    ][:8]
    requirement_rows = [
        [
            r["ticker"],
            r["company"],
            fmt_pct(r["price_premium_pct"]),
            cny_yi(r["premium_market_cap"]),
            cny_yi(r["required_growth_net_profit_base_margin_30pct"]),
            cny_yi(r["required_growth_revenue_base_margin_30pct"]),
            fmt_pct(r["required_revenue_vs_2026e_pct"]),
            r["evidence_gap"],
        ]
        for r in implied_growth_requirement_rows(rows)
    ]
    return "# 隐含增长敏感性\n\n" + textwrap.dedent(
        """\
        门禁状态：有条件通过。由于缺少公司级订单、合同ASP和毛利率，本报告不把AI存储或WF6需求直接折成EPS；敏感性分析以“哪些证据能改变估值信用”为核心。公开价格代理已经补齐，但仍只能作为跟踪变量和市场锚，不能替代公司合同ASP。
        """
    ) + "\n\n## 驱动敏感性\n\n" + md_table(
        ["变量", "悲观", "基准", "乐观", "估值影响"],
        sensitivity_rows,
    ) + "\n\n## 公开价格代理边界\n\n" + md_table(
        ["主题", "代理项", "数值", "趋势", "估值用途", "仍缺字段"],
        price_rows,
    ) + "\n\n## 当前股价隐含增长要求\n\n" + md_table(
        ["代码", "名称", "当前价隐含要求", "敏感变量", "证据缺口"],
        ticker_rows,
    ) + "\n\n## 隐含增长反推门槛\n\n" + md_table(
        ["代码", "名称", "溢价", "溢价市值", "所需增量净利", "所需增长收入", "收入/2026E", "证据缺口"],
        requirement_rows,
    )


