def structured_data_provenance_packet(captured: list[dict[str, Any]], failed: list[dict[str, Any]]) -> dict[str, Any]:
    rows = structured_data_provenance_rows(captured, failed)
    return {
        "schema": "astock.structured_data_provenance.v1",
        "generated_at": now_cst(),
        "gate_status": "CONDITIONAL",
        "rows": rows,
        "coverage_summary": {
            "covered_tickers": 18,
            "datasets": len(rows),
            "hard_remaining_gaps": [
                "公司合同ASP/价格区间",
                "单品订单金额/长单条款",
                "单品收入拆分",
                "单品毛利率",
                "单品客户份额和客户侧验证",
                "半导体高纯钨材客户、订单和收入",
            ],
        },
    }


def structured_data_provenance_md(captured: list[dict[str, Any]], failed: list[dict[str, Any]]) -> str:
    rows = structured_data_provenance_rows(captured, failed)
    return "# 结构化数据来源覆盖与健康\n\n门禁状态：有条件通过。本表把报告中进入估值、供应链、增长业绩和风险判断的结构化数据源统一登记，区分原始公开来源、接口快照和AStock派生模型。它证明“已补字段从哪里来”，也明确哪些硬缺口不能由公开接口替代。\n\n" + md_table(
        ["数据包", "来源类型", "来源名称", "覆盖", "关键字段", "质量", "限制", "下游用途"],
        [[r["dataset"], r["source_type"], r["source_name"], r["coverage"], r["material_fields"], r["quality_tier"], r["limitations"], r["downstream_use"]] for r in rows],
    ) + "\n\n硬缺口仍为公司合同ASP、单品订单金额/长单条款、单品收入拆分、单品毛利率、具名客户份额和半导体高纯钨材客户/订单/收入。上述缺口在公开接口层面不能被假设补齐，只能通过后续公告、年报附注、调研纪要或券商全文验证。\n"


def source_registry_md(captured: list[dict[str, Any]], failed: list[dict[str, Any]]) -> str:
    rows = []
    for s in captured + failed:
        status = "已归档" if s.get("capture_status", "ok") == "ok" else "抓取失败"
        rows.append([s["id"], source_level_cn(s["level"]), s["title"], status, s.get("path", "未归档"), s["url"]])
    return "# 来源登记\n\n## 原始网页/PDF归档\n\n" + md_table(["编号", "层级", "标题", "状态", "归档路径", "网址"], rows) + "\n\n## 结构化数据源摘要\n\n" + md_table(
        ["数据包", "来源名称", "覆盖", "质量", "限制"],
        [[r["dataset"], r["source_name"], r["coverage"], r["quality_tier"], r["limitations"]] for r in structured_data_provenance_rows(captured, failed)],
    )


def claim_audit_md() -> str:
    audit = build_claim_audit()
    rows = [[c["claim"], ",".join(c["source_ids"]), evidence_cn(c["confidence"]), bool_cn(c["allowed_in_report"])] for c in audit["claims"]]
    return "# 声明审计\n\n" + md_table(["结论", "来源", "置信度", "可入正文"], rows)


