def growth_proxy_pdf_text(value: Any) -> str:
    text = reader_text(value)
    if "历史官方订单金额样本" in text:
        return "产能/产销 + 历史合同金额样本；盈利转化字段未披露"
    if "订单/ASP/产能代理未披露" in text:
        if "特气产品" in text and "前驱体材料" in text:
            return "特气/前驱体平台；订单/ASP未披露"
        if "电子级氯气/氯化氢" in text:
            return "电子级氯气/氯化氢；订单/ASP未披露"
        if "稀有气体/工业尾气" in text:
            return "稀有气体/尾气回收；订单/ASP未披露"
        if "特种气体" in text or "大宗气体" in text:
            return "综合气体/特种气体；订单/ASP未披露"
        return "电子气体平台证据；订单/ASP未披露"
    replacements = {
        "基准业务看制冷剂配额/价差；电子材料客户和订单未披露": "制冷剂配额/价差已入基准；电子材料订单未披露",
        "产品页披露电子级WF6 5N及100吨/年项目口径": "电子级WF6 5N；100吨/年项目",
        "高纯WF6产能600吨；暂无扩产计划": "高纯WF6产能600吨；暂无扩产",
        "WF6现有产能2000吨/年、6N级": "WF6产能2000吨/年、6N级",
        "WF6现有产能2000吨/年、6N级；3383吨电子气体项目有公告/环评证据，WF6单品新增拆分未由官方证实": "WF6 2000吨/年；3383吨项目有官方证据",
        "无WF6合成产能；仅按部分客户要求供应纯化WF6": "无合成产能；按需纯化供应",
    }
    return replacements.get(text, text)


